// Tokenizer for the Nix language producing a lossless token stream.
use crate::kinds::SyntaxKind::{self, *};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Context {
    StringBody { multiline: bool },
    StringEnd,
    Interpol { brackets: u32 },
    InterpolStart,
    Path,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum IdentType {
    Path,
    Store,
    Uri,
}

fn is_valid_path_char(c: char) -> bool {
    matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '/' | '_' | '.' | '+' | '-')
}

fn is_valid_uri_char(c: char) -> bool {
    match c {
        '%' | '/' | '?' | ':' | '@' | '&' | '=' | '+' | '$' | ',' | '-' | '_' | '.' | '!' | '~'
        | '*' | '\'' => true,
        _ => c.is_ascii_alphanumeric(),
    }
}

pub struct Tokenizer<'a> {
    ctx: Vec<Context>,
    input: &'a str,
    offset: usize,
}

impl<'a> Tokenizer<'a> {
    pub fn new(input: &'a str) -> Self {
        Tokenizer { ctx: Vec::new(), input, offset: 0 }
    }

    fn remaining(&self) -> &'a str {
        &self.input[self.offset..]
    }
    fn peek(&self) -> Option<char> {
        self.remaining().chars().next()
    }
    fn next_char(&mut self) -> Option<char> {
        let c = self.peek();
        if let Some(c) = c {
            self.offset += c.len_utf8();
        }
        c
    }
    fn starts_with_bump(&mut self, s: &str) -> bool {
        if self.remaining().starts_with(s) {
            self.offset += s.len();
            true
        } else {
            false
        }
    }
    fn consume<F: FnMut(char) -> bool>(&mut self, mut f: F) -> usize {
        let len: usize = self
            .remaining()
            .chars()
            .take_while(|&c| f(c))
            .map(|c| c.len_utf8())
            .sum();
        self.offset += len;
        len
    }
    fn push_ctx(&mut self, ctx: Context) {
        self.ctx.push(ctx)
    }
    fn pop_ctx(&mut self, _ctx: Context) {
        self.ctx.pop();
    }

    fn next_string(&mut self, multiline: bool) -> SyntaxKind {
        loop {
            let start = self.offset;
            match self.next_char() {
                None => {
                    self.pop_ctx(Context::StringBody { multiline });
                    return TOKEN_ERROR;
                }
                Some('$') if self.peek() == Some('$') => {
                    self.next_char();
                }
                Some('$') if self.peek() == Some('{') => {
                    self.offset = start;
                    self.push_ctx(Context::InterpolStart);
                    return TOKEN_STRING_CONTENT;
                }
                Some('\\') if !multiline => {
                    self.next_char();
                }
                Some('"') if !multiline => {
                    self.offset = start;
                    self.pop_ctx(Context::StringBody { multiline: false });
                    self.push_ctx(Context::StringEnd);
                    return TOKEN_STRING_CONTENT;
                }
                Some('\'') if multiline => match self.peek() {
                    None => {
                        self.pop_ctx(Context::StringBody { multiline: true });
                        return TOKEN_ERROR;
                    }
                    Some('\'') => {
                        let mut it = self.remaining().chars();
                        it.next();
                        match it.next() {
                            Some('\'') | Some('\\') | Some('$') => {
                                self.next_char();
                                self.next_char();
                            }
                            _ => {
                                self.offset = start;
                                self.pop_ctx(Context::StringBody { multiline: true });
                                self.push_ctx(Context::StringEnd);
                                return TOKEN_STRING_CONTENT;
                            }
                        }
                    }
                    _ => (),
                },
                _ => (),
            }
        }
    }

    pub fn next_token(&mut self) -> Option<(SyntaxKind, &'a str)> {
        let start = self.offset;
        let kind = self.next_inner(start)?;
        Some((kind, &self.input[start..self.offset]))
    }

    fn next_inner(&mut self, start: usize) -> Option<SyntaxKind> {
        loop {
            match self.ctx.last().copied() {
                Some(Context::InterpolStart) => {
                    self.pop_ctx(Context::InterpolStart);
                    self.ctx.push(Context::Interpol { brackets: 0 });
                    if self.starts_with_bump("${") {
                        return Some(TOKEN_INTERPOL_START);
                    } else {
                        unreachable!()
                    }
                }
                Some(Context::Path) => {
                    if self.starts_with_bump("${") {
                        self.ctx.push(Context::Interpol { brackets: 0 });
                        return Some(TOKEN_INTERPOL_START);
                    } else if self.peek().map_or(false, is_valid_path_char) {
                        while self.peek().map_or(false, is_valid_path_char) {
                            self.next_char();
                            if self.remaining().starts_with("${") {
                                break;
                            }
                        }
                        return Some(TOKEN_PATH);
                    } else {
                        self.pop_ctx(Context::Path);
                        continue;
                    }
                }
                Some(Context::StringBody { multiline }) => {
                    let token = self.next_string(multiline);
                    if self.offset == start {
                        continue;
                    }
                    return Some(token);
                }
                Some(Context::StringEnd) => {
                    self.pop_ctx(Context::StringEnd);
                    let status = match self.peek() {
                        Some('"') => {
                            self.next_char();
                            true
                        }
                        Some('\'') => {
                            self.next_char();
                            match self.peek() {
                                Some('\'') => {
                                    self.next_char();
                                    true
                                }
                                _ => false,
                            }
                        }
                        _ => false,
                    };
                    return Some(if status { TOKEN_STRING_END } else { TOKEN_ERROR });
                }
                _ => (),
            }
            break;
        }

        // Check if it's a path
        let store_path = self.peek() == Some('<');
        let kind = {
            let rem = self.remaining();
            let mut skipped = String::new();
            for c in rem.chars() {
                let ok = match c {
                    '<' | '/' => store_path,
                    _ => is_valid_path_char(c),
                };
                if !ok {
                    break;
                }
                skipped.push(c);
            }
            let mut lookahead = rem[skipped.len()..].chars();
            match (lookahead.next(), lookahead.next()) {
                (Some('/'), Some('/')) => None,
                (Some('/'), Some('*')) => None,
                (Some('/'), Some(c)) if !c.is_whitespace() => Some(IdentType::Path),
                (Some('>'), _) => Some(IdentType::Store),
                (Some(':'), Some(c)) if is_valid_uri_char(c) && !skipped.contains('_') => {
                    Some(IdentType::Uri)
                }
                _ => None,
            }
        };

        let c = self.next_char()?;

        if c == '~' || kind == Some(IdentType::Path) {
            if c == '~' && self.next_char() != Some('/') {
                return Some(TOKEN_ERROR);
            }
            self.consume(is_valid_path_char);
            let ident = &self.input[start..self.offset];
            if self.remaining().starts_with("${") {
                self.ctx.push(Context::Path);
            } else if ident.ends_with('/') {
                return Some(TOKEN_ERROR);
            }
            return Some(TOKEN_PATH);
        }

        let kind = match c {
            // Trivia
            c if c.is_whitespace() => {
                self.consume(char::is_whitespace);
                TOKEN_WHITESPACE
            }
            '#' => {
                self.consume(|c| c != '\n');
                TOKEN_COMMENT
            }
            '/' if self.peek() == Some('*') => {
                self.next_char();
                loop {
                    if self.starts_with_bump("*/") {
                        break TOKEN_COMMENT;
                    }
                    if self.next_char().is_none() {
                        return Some(TOKEN_ERROR);
                    }
                }
            }
            '<' if kind == Some(IdentType::Store) => {
                self.consume(|c| c != '>');
                self.next_char();
                TOKEN_PATH
            }
            '=' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_EQUAL
            }
            '!' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_NOT_EQUAL
            }
            '!' => TOKEN_INVERT,
            '{' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    *brackets += 1;
                }
                TOKEN_L_BRACE
            }
            '}' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    match brackets.checked_sub(1) {
                        Some(new) => *brackets = new,
                        None => {
                            self.pop_ctx(Context::Interpol { brackets: 0 });
                            return Some(TOKEN_INTERPOL_END);
                        }
                    }
                }
                TOKEN_R_BRACE
            }
            '[' => TOKEN_L_BRACK,
            ']' => TOKEN_R_BRACK,
            '@' => TOKEN_AT,
            ':' => TOKEN_COLON,
            ',' => TOKEN_COMMA,
            '.' => {
                if self.peek().map_or(false, |x| x.is_ascii_digit()) {
                    self.consume(|c| c.is_ascii_digit());
                    self.consume_scientific()
                } else if self.starts_with_bump("..") {
                    TOKEN_ELLIPSIS
                } else {
                    TOKEN_DOT
                }
            }
            '=' => TOKEN_ASSIGN,
            '?' => TOKEN_QUESTION,
            ';' => TOKEN_SEMICOLON,
            '(' => TOKEN_L_PAREN,
            ')' => TOKEN_R_PAREN,
            '+' if self.peek() == Some('+') => {
                self.next_char();
                TOKEN_CONCAT
            }
            '-' if self.peek() == Some('>') => {
                self.next_char();
                TOKEN_IMPLICATION
            }
            '/' if self.peek() == Some('/') => {
                self.next_char();
                TOKEN_UPDATE
            }
            '+' => TOKEN_ADD,
            '-' => TOKEN_SUB,
            '*' => TOKEN_MUL,
            '/' => TOKEN_DIV,
            '<' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_LESS_OR_EQ
            }
            '<' => TOKEN_LESS,
            '>' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_MORE_OR_EQ
            }
            '>' => TOKEN_MORE,
            '&' if self.peek() == Some('&') => {
                self.next_char();
                TOKEN_AND_AND
            }
            '|' if self.peek() == Some('|') => {
                self.next_char();
                TOKEN_OR_OR
            }
            '"' => {
                self.push_ctx(Context::StringBody { multiline: false });
                TOKEN_STRING_START
            }
            '\'' if self.peek() == Some('\'') => {
                self.next_char();
                self.push_ctx(Context::StringBody { multiline: true });
                TOKEN_STRING_START
            }
            '$' if self.peek() == Some('{') => {
                self.next_char();
                self.push_ctx(Context::Interpol { brackets: 0 });
                TOKEN_INTERPOL_START
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                if kind == Some(IdentType::Uri) {
                    self.consume(is_valid_uri_char);
                    TOKEN_URI
                } else {
                    self.consume(|c| {
                        matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-' | '\'')
                    });
                    match &self.input[start..self.offset] {
                        "assert" => TOKEN_ASSERT,
                        "else" => TOKEN_ELSE,
                        "if" => TOKEN_IF,
                        "in" => TOKEN_IN,
                        "inherit" => TOKEN_INHERIT,
                        "let" => TOKEN_LET,
                        "or" => TOKEN_OR,
                        "rec" => TOKEN_REC,
                        "then" => TOKEN_THEN,
                        "with" => TOKEN_WITH,
                        _ => TOKEN_IDENT,
                    }
                }
            }
            '0'..='9' => {
                self.consume(|c| c.is_ascii_digit());
                if self.peek() == Some('.') {
                    self.next_char();
                    self.consume(|c| c.is_ascii_digit());
                    self.consume_scientific()
                } else {
                    TOKEN_INTEGER
                }
            }
            _ => TOKEN_ERROR,
        };
        Some(kind)
    }

    fn consume_scientific(&mut self) -> SyntaxKind {
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.next_char();
            if self.peek() == Some('-') || self.peek() == Some('+') {
                self.next_char();
            }
            if self.consume(|c| c.is_ascii_digit()) == 0 {
                return TOKEN_ERROR;
            }
        }
        TOKEN_FLOAT
    }
}

pub fn tokenize(input: &str) -> Vec<(SyntaxKind, &str)> {
    let mut t = Tokenizer::new(input);
    let mut out = Vec::new();
    while let Some(tok) = t.next_token() {
        out.push(tok);
    }
    out
}
