            '[' => TOKEN_L_BRACK,
            ']' => TOKEN_R_BRACK,
            '@' => TOKEN_AT,
            ':' => TOKEN_COLON,
            ',' => TOKEN_COMMA,
            '.' => {
                if self.peek().map_or(false, |x| x.is_ascii_digit()) {
                    self.consume(|c| c.is_ascii_digit());
                    self.consume_scientific()
                } else if self.starts_with_bump("..") {
                    TOKEN_ELLIPSIS
                } else {
                    TOKEN_DOT
                }
            }
            '=' => TOKEN_ASSIGN,
            '?' => TOKEN_QUESTION,
            ';' => TOKEN_SEMICOLON,
            '(' => TOKEN_L_PAREN,
            ')' => TOKEN_R_PAREN,
            '+' if self.peek() == Some('+') => {
                self.next_char();
                TOKEN_CONCAT
            }
            '-' if self.peek() == Some('>') => {
                self.next_char();
                TOKEN_IMPLICATION
            }
            '/' if self.peek() == Some('/') => {
                self.next_char();
                TOKEN_UPDATE
            }
            '+' => TOKEN_ADD,
            '-' => TOKEN_SUB,
            '*' => TOKEN_MUL,
            '/' => TOKEN_DIV,
            '<' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_LESS_OR_EQ
            }
            '<' => TOKEN_LESS,
            '>' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_MORE_OR_EQ
            }
            '>' => TOKEN_MORE,
            '&' if self.peek() == Some('&') => {
                self.next_char();
                TOKEN_AND_AND
            }
            '|' if self.peek() == Some('|') => {
                self.next_char();
                TOKEN_OR_OR
            }
            '"' => {
                self.push_ctx(Context::StringBody { multiline: false });
                TOKEN_STRING_START
            }
            '\'' if self.peek() == Some('\'') => {
                self.next_char();
                self.push_ctx(Context::StringBody { multiline: true });
                TOKEN_STRING_START
            }
            '$' if self.peek() == Some('{') => {
                self.next_char();
                self.push_ctx(Context::Interpol { brackets: 0 });
                TOKEN_INTERPOL_START
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                if kind == Some(IdentType::Uri) {
                    self.consume(is_valid_uri_char);
                    TOKEN_URI
                } else {
                    self.consume(|c| {
                        matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-' | '\'')
                    });
                    match &self.input[start..self.offset] {
                        "assert" => TOKEN_ASSERT,
                        "else" => TOKEN_ELSE,
                        "if" => TOKEN_IF,
                        "in" => TOKEN_IN,
                        "inherit" => TOKEN_INHERIT,
                        "let" => TOKEN_LET,
                        "or" => TOKEN_OR,
                        "rec" => TOKEN_REC,
                        "then" => TOKEN_THEN,
                        "with" => TOKEN_WITH,
                        _ => TOKEN_IDENT,
                    }
                }
            }
            '0'..='9' => {
                self.consume(|c| c.is_ascii_digit());
                if self.peek() == Some('.') {
                    self.next_char();
                    self.consume(|c| c.is_ascii_digit());
                    self.consume_scientific()
                } else {
                    TOKEN_INTEGER
                }
            }
            _ => TOKEN_ERROR,
        };
        Some(kind)
    }

    fn consume_scientific(&mut self) -> SyntaxKind {
        if self.peek() == Some('e') || self.peek() == Some('E') {
            self.next_char();
            if self.peek() == Some('-') || self.peek() == Some('+') {
                self.next_char();
            }
            if self.consume(|c| c.is_ascii_digit()) == 0 {
                return TOKEN_ERROR;
            }
        }
        TOKEN_FLOAT
    }
}

pub fn tokenize(input: &str) -> Vec<(SyntaxKind, &str)> {
    let mut t = Tokenizer::new(input);
    let mut out = Vec::new();
    while let Some(tok) = t.next_token() {
        out.push(tok);
    }
    out
}
