// Typed-ish accessors over the syntax tree.
use crate::kinds::SyntaxKind::{self, *};
use crate::tree::{is_expr_kind, Id, Tree};

pub fn expr_children(t: &Tree, id: Id) -> Vec<Id> {
    t.children(id).filter(|&c| is_expr_kind(t.kind(c))).collect()
}

pub fn first_child_of_kind(t: &Tree, id: Id, kind: SyntaxKind) -> Option<Id> {
    t.children(id).find(|&c| t.kind(c) == kind)
}

pub fn children_of_kind(t: &Tree, id: Id, kind: SyntaxKind) -> Vec<Id> {
    t.children(id).filter(|&c| t.kind(c) == kind).collect()
}

pub fn first_token_of_kind(t: &Tree, id: Id, kind: SyntaxKind) -> Option<Id> {
    t.child_tokens(id).find(|&c| t.kind(c) == kind)
}

pub fn nth_expr(t: &Tree, id: Id, n: usize) -> Option<Id> {
    t.children(id).filter(|&c| is_expr_kind(t.kind(c))).nth(n)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BinOpKind {
    Concat,
    Update,
    Add,
    Sub,
    Mul,
    Div,
    And,
    Equal,
    Implication,
    Less,
    LessOrEq,
    More,
    MoreOrEq,
    NotEqual,
    Or,
}

impl BinOpKind {
    pub fn from_kind(k: SyntaxKind) -> Option<BinOpKind> {
        Some(match k {
            TOKEN_CONCAT => BinOpKind::Concat,
            TOKEN_UPDATE => BinOpKind::Update,
            TOKEN_ADD => BinOpKind::Add,
            TOKEN_SUB => BinOpKind::Sub,
            TOKEN_MUL => BinOpKind::Mul,
            TOKEN_DIV => BinOpKind::Div,
            TOKEN_AND_AND => BinOpKind::And,
            TOKEN_EQUAL => BinOpKind::Equal,
            TOKEN_IMPLICATION => BinOpKind::Implication,
            TOKEN_LESS => BinOpKind::Less,
            TOKEN_LESS_OR_EQ => BinOpKind::LessOrEq,
            TOKEN_MORE => BinOpKind::More,
            TOKEN_MORE_OR_EQ => BinOpKind::MoreOrEq,
            TOKEN_NOT_EQUAL => BinOpKind::NotEqual,
            TOKEN_OR_OR => BinOpKind::Or,
            _ => return None,
        })
    }
}

pub fn binop_operator(t: &Tree, id: Id) -> Option<BinOpKind> {
    t.child_tokens(id).find_map(|c| BinOpKind::from_kind(t.kind(c)))
}

pub fn binop_lhs(t: &Tree, id: Id) -> Option<Id> {
    nth_expr(t, id, 0)
}

pub fn binop_rhs(t: &Tree, id: Id) -> Option<Id> {
    nth_expr(t, id, 1)
}

/// Attr components of an attrpath node.
pub fn attrpath_attrs(t: &Tree, attrpath: Id) -> Vec<Id> {
    t.children(attrpath)
        .filter(|&c| matches!(t.kind(c), NODE_IDENT | NODE_STRING | NODE_DYNAMIC))
        .collect()
}

pub fn ident_text(t: &Tree, id: Id) -> Option<String> {
    if t.kind(id) != NODE_IDENT {
        return None;
    }
    let tok = first_token_of_kind(t, id, TOKEN_IDENT)?;
    Some(t.text(tok).to_string())
}

/// Entries of a set-like node (attrset, let-in, legacy let): attrpath values and inherits,
/// in source order.
pub fn entries(t: &Tree, id: Id) -> Vec<Id> {
    t.children(id).filter(|&c| matches!(t.kind(c), NODE_ATTRPATH_VALUE | NODE_INHERIT)).collect()
}

pub fn attrpath_values(t: &Tree, id: Id) -> Vec<Id> {
    children_of_kind(t, id, NODE_ATTRPATH_VALUE)
}

pub fn inherits(t: &Tree, id: Id) -> Vec<Id> {
    children_of_kind(t, id, NODE_INHERIT)
}

pub fn inherit_attrs(t: &Tree, id: Id) -> Vec<Id> {
    t.children(id)
        .filter(|&c| matches!(t.kind(c), NODE_IDENT | NODE_STRING | NODE_DYNAMIC))
        .collect()
}
