// Helpers to build replacement snippets by parsing a template.
use crate::kinds::SyntaxKind::{self, *};
use crate::parser;
use crate::tree::Tree;

/// Parse `text`, panicking (like the reference implementation) if it does not parse cleanly,
/// and return the text of the first node of `kind` (in preorder).
fn ast_from_text(text: &str, kind: SyntaxKind) -> String {
    let p = parser::parse(text);
    if !p.errors.is_empty() {
        crate::util::panic_at("lib/src/make.rs:13:9", &format!("Failed to parse `{:?}`", text));
    }
    let tree = Tree::from_green(&p.green);
    for id in tree.descendants(tree.root()) {
        if tree.kind(id) == kind {
            return tree.text(id).to_string();
        }
    }
    crate::util::panic_at(
        "lib/src/make.rs:18:9",
        &format!("Failed to make ast node `{:?}` from text `{}`", kind, text),
    );
}

pub fn parenthesize(node: &str) -> String {
    ast_from_text(&format!("({})", node), NODE_PAREN)
}

pub fn quote(node: &str) -> String {
    ast_from_text(&format!("\"{}\"", node), NODE_STRING)
}

pub fn unary_not(node: &str) -> String {
    ast_from_text(&format!("!{}", node), NODE_UNARY_OP)
}

pub fn inherit_stmt(nodes: &[&str]) -> String {
    let inherited = nodes.join(" ");
    ast_from_text(&format!("{{ inherit {}; }}", inherited), NODE_INHERIT)
}

pub fn inherit_from_stmt(from: &str, nodes: &[&str]) -> String {
    let inherited = nodes.join(" ");
    ast_from_text(&format!("{{ inherit ({}) {}; }}", from, inherited), NODE_INHERIT)
}

pub fn attrset(inherits: &[String], entries: &[String], recursive: bool) -> String {
    let mut buffer = String::new();
    buffer.push_str(if recursive { "rec {\n" } else { "{\n" });
    for i in inherits {
        buffer.push_str(&format!("  {}\n", i));
    }
    for e in entries {
        buffer.push_str(&format!("  {}\n", e));
    }
    buffer.push('}');
    ast_from_text(&buffer, NODE_ATTR_SET)
}

pub fn select(set: &str, index: &str) -> String {
    ast_from_text(&format!("{}.{}", set, index), NODE_SELECT)
}

pub fn ident(text: &str) -> String {
    ast_from_text(text, NODE_IDENT)
}

pub fn binary(lhs: &str, op: &str, rhs: &str) -> String {
    ast_from_text(&format!("{} {} {}", lhs, op, rhs), NODE_BIN_OP)
}

pub fn or_default(set: &str, index: &str, default: &str) -> String {
    ast_from_text(&format!("{}.{} or {}", set, index, default), NODE_SELECT)
}
