// The lints themselves.
use crate::ast::*;
use crate::kinds::SyntaxKind::{self, *};
use crate::make;
use crate::report::Report;
use crate::tree::{Id, Tree};

pub struct LintMeta {
    pub name: &'static str,
    pub note: &'static str,
    pub code: u32,
}

pub const LINTS: &[LintMeta] = &[
    LintMeta { name: "bool_comparison", note: "Unnecessary comparison with boolean", code: 1 },
    LintMeta { name: "empty_let_in", note: "Useless let-in expression", code: 2 },
    LintMeta { name: "manual_inherit", note: "Assignment instead of inherit", code: 3 },
    LintMeta { name: "manual_inherit_from", note: "Assignment instead of inherit from", code: 4 },
    LintMeta { name: "legacy_let_syntax", note: "Using undocumented `let` syntax", code: 5 },
    LintMeta { name: "collapsible_let_in", note: "These let-in expressions are collapsible", code: 6 },
    LintMeta { name: "eta_reduction", note: "This function expression is eta reducible", code: 7 },
    LintMeta { name: "useless_parens", note: "These parentheses can be omitted", code: 8 },
    LintMeta { name: "empty_pattern", note: "Found empty pattern in function argument", code: 10 },
    LintMeta {
        name: "redundant_pattern_bind",
        note: "Found redundant pattern bind in function argument",
        code: 11,
    },
    LintMeta { name: "unquoted_uri", note: "Found unquoted URI expression", code: 12 },
    LintMeta { name: "empty_inherit", note: "Found empty inherit statement", code: 14 },
    LintMeta {
        name: "deprecated_to_path",
        note: "Found usage of deprecated builtin toPath",
        code: 17,
    },
    LintMeta {
        name: "bool_simplification",
        note: "This boolean expression can be simplified",
        code: 18,
    },
    LintMeta {
        name: "useless_has_attr",
        note: "This `if` expression can be simplified with `or`",
        code: 19,
    },
    LintMeta { name: "repeated_keys", note: "Avoid repeated keys in attribute sets", code: 20 },
    LintMeta {
        name: "empty_list_concat",
        note: "Unnecessary concatenation with empty list",
        code: 23,
    },
];

fn meta(code: u32) -> &'static LintMeta {
    LINTS.iter().find(|l| l.code == code).unwrap()
}

fn report(code: u32) -> Report {
    Report::new(meta(code).note, code)
}

/// Which lint codes apply to elements of the given kind, in registration order.
pub fn lints_for_kind(kind: SyntaxKind) -> &'static [u32] {
    match kind {
        NODE_BIN_OP => &[1, 23],
        NODE_LET_IN => &[2, 6, 8],
        NODE_ATTRPATH_VALUE => &[3, 4, 8, 20],
        NODE_LEGACY_LET => &[5],
        NODE_LAMBDA => &[7],
        NODE_PAREN => &[8],
        NODE_PATTERN => &[10, 11],
        TOKEN_URI => &[12],
        NODE_INHERIT => &[14],
        NODE_APPLY => &[17],
        NODE_UNARY_OP => &[18],
        NODE_IF_ELSE => &[19],
        _ => &[],
    }
}

pub fn run_lint(code: u32, t: &Tree, id: Id) -> Option<Report> {
    match code {
        1 => bool_comparison(t, id),
        2 => empty_let_in(t, id),
        3 => manual_inherit(t, id),
        4 => manual_inherit_from(t, id),
        5 => legacy_let_syntax(t, id),
        6 => collapsible_let_in(t, id),
        7 => eta_reduction(t, id),
        8 => useless_parens(t, id),
        10 => empty_pattern(t, id),
        11 => redundant_pattern_bind(t, id),
        12 => unquoted_uri(t, id),
        14 => empty_inherit(t, id),
        17 => deprecated_to_path(t, id),
        18 => bool_simplification(t, id),
        19 => useless_has_attr(t, id),
        20 => repeated_keys(t, id),
        23 => empty_list_concat(t, id),
        _ => None,
    }
}

#[derive(PartialEq, Eq, Clone, Copy)]
enum NixBoolean {
    True,
    False,
}

fn boolean_ident(t: &Tree, id: Id) -> Option<NixBoolean> {
    match ident_text(t, id)?.as_str() {
        "true" => Some(NixBoolean::True),
        "false" => Some(NixBoolean::False),
        _ => None,
    }
}

fn bool_comparison(t: &Tree, node: Id) -> Option<Report> {
    let lhs = binop_lhs(t, node)?;
    let rhs = binop_rhs(t, node)?;
    let op = binop_operator(t, node)?;
    if op != BinOpKind::Equal && op != BinOpKind::NotEqual {
        return None;
    }
    let (non_bool_side, bool_side) = if boolean_ident(t, lhs).is_some() {
        (rhs, lhs)
    } else if boolean_ident(t, rhs).is_some() {
        (lhs, rhs)
    } else {
        return None;
    };
    let at = t.range(node);
    let replacement = match (boolean_ident(t, bool_side).unwrap(), op == BinOpKind::Equal) {
        (NixBoolean::True, true) | (NixBoolean::False, false) => t.text(non_bool_side).to_string(),
        _ => match t.kind(non_bool_side) {
            NODE_APPLY | NODE_PAREN | NODE_IDENT | NODE_HAS_ATTR => {
                make::unary_not(t.text(non_bool_side))
            }
            _ => {
                let parens = make::parenthesize(t.text(non_bool_side));
                make::unary_not(&parens)
            }
        },
    };
    let message = format!(
        "Comparing `{}` with boolean literal `{}`",
        t.text(non_bool_side),
        t.text(bool_side)
    );
    Some(report(1).suggest(at, message, at, replacement))
}

fn let_body(t: &Tree, node: Id) -> Option<Id> {
    nth_expr(t, node, 0)
}

fn empty_let_in(t: &Tree, node: Id) -> Option<Report> {
    if !entries(t, node).is_empty() {
        return None;
    }
    let body = let_body(t, node)?;
    let has_comments = t.children_with_tokens(node).iter().any(|&c| t.kind(c) == TOKEN_COMMENT);
    let at = t.range(node);
    let message = "This let-in expression has no entries";
    Some(if has_comments {
        report(2).diagnostic(at, message)
    } else {
        report(2).suggest(at, message, at, t.text(body))
    })
}

fn single_ident_key(t: &Tree, node: Id) -> Option<Id> {
    let attrpath = first_child_of_kind(t, node, NODE_ATTRPATH)?;
    let attrs = attrpath_attrs(t, attrpath);
    if attrs.len() != 1 {
        return None;
    }
    let key = attrs[0];
    if t.kind(key) != NODE_IDENT {
        return None;
    }
    Some(key)
}

fn kv_value(t: &Tree, node: Id) -> Option<Id> {
    nth_expr(t, node, 0)
}

fn manual_inherit(t: &Tree, node: Id) -> Option<Report> {
    let key = single_ident_key(t, node)?;
    let value = kv_value(t, node)?;
    if t.kind(value) != NODE_IDENT {
        return None;
    }
    if t.text(key) != t.text(value) {
        return None;
    }
    let at = t.range(node);
    let replacement = make::inherit_stmt(&[t.text(key)]);
    let message = "This assignment is better written with `inherit`";
    Some(report(3).suggest(at, message, at, replacement))
}

fn manual_inherit_from(t: &Tree, node: Id) -> Option<Report> {
    let key = single_ident_key(t, node)?;
    let value = kv_value(t, node)?;
    if t.kind(value) != NODE_SELECT {
        return None;
    }
    let attrpath = first_child_of_kind(t, value, NODE_ATTRPATH)?;
    let attrs = attrpath_attrs(t, attrpath);
    if attrs.len() != 1 {
        return None;
    }
    let index = attrs[0];
    if t.kind(index) != NODE_IDENT {
        return None;
    }
    if t.text(key) != t.text(index) {
        return None;
    }
    let at = t.range(node);
    let set = nth_expr(t, value, 0)?;
    let replacement = make::inherit_from_stmt(t.text(set), &[t.text(key)]);
    let message = "This assignment is better written with `inherit`";
    Some(report(4).suggest(at, message, at, replacement))
}

fn first_attr_is_ident(t: &Tree, kv: Id, name: &str) -> bool {
    let attrpath = match first_child_of_kind(t, kv, NODE_ATTRPATH) {
        Some(a) => a,
        None => return false,
    };
    match attrpath_attrs(t, attrpath).first() {
        Some(&first) => ident_text(t, first).as_deref() == Some(name),
        None => false,
    }
}

fn legacy_let_syntax(t: &Tree, node: Id) -> Option<Report> {
    if !attrpath_values(t, node).iter().any(|&kv| first_attr_is_ident(t, kv, "body")) {
        return None;
    }
    let inherits: Vec<String> = inherits(t, node).iter().map(|&i| t.text(i).to_string()).collect();
    let entries: Vec<String> = entries(t, node).iter().map(|&i| t.text(i).to_string()).collect();
    let attrset = make::attrset(&inherits, &entries, true);
    let body = make::ident("body");
    let selected = make::select(&attrset, &body);
    let at = t.range(node);
    let message = "Prefer `rec` over undocumented `let` syntax";
    Some(report(5).suggest(at, message, at, selected))
}

fn collapsible_let_in(t: &Tree, node: Id) -> Option<Report> {
    let body = let_body(t, node)?;
    if t.kind(body) != NODE_LET_IN {
        return None;
    }
    let first_annotation = t.range(node);
    let first_message = "This `let in` expression contains a nested `let in` expression";
    let second_annotation = t.range(body);
    let second_message = "This `let in` expression is nested";

    // find `in` token among previous siblings of body (including body itself)
    let mut start = None;
    let mut cur = Some(body);
    while let Some(c) = cur {
        if t.kind(c) == TOKEN_IN {
            start = Some(t.range(c).0);
            break;
        }
        cur = t.prev_sibling_or_token(c);
    }
    let start = start?;
    let end = t
        .preorder_with_tokens(body)
        .into_iter()
        .find(|&e| t.kind(e) == TOKEN_LET)
        .map(|e| t.range(e).1)?;
    Some(report(6).diagnostic(first_annotation, first_message).suggest(
        second_annotation,
        second_message,
        (start, end),
        "",
    ))
}

fn eta_reduction(t: &Tree, node: Id) -> Option<Report> {
    let param = t.children(node).next()?;
    if t.kind(param) != NODE_IDENT_PARAM {
        return None;
    }
    let arg = first_child_of_kind(t, param, NODE_IDENT)?;
    let body = nth_expr(t, node, 0)?;
    if t.kind(body) != NODE_APPLY {
        return None;
    }
    let value = nth_expr(t, body, 1)?;
    if t.kind(value) != NODE_IDENT {
        return None;
    }
    if t.text(arg) != t.text(value) {
        return None;
    }
    let lambda = nth_expr(t, body, 0)?;
    // the function must not mention the argument
    let arg_text = t.text(arg);
    let mentions = t
        .descendants(lambda)
        .into_iter()
        .any(|d| t.kind(d) == NODE_IDENT && t.text(d) == arg_text);
    if mentions {
        return None;
    }
    if t.kind(lambda) != NODE_IDENT {
        return None;
    }
    let at = t.range(node);
    let message = format!("Found eta-reduction: `{}`", t.text(lambda));
    Some(report(7).suggest(at, message, at, t.text(lambda)))
}

fn paren_inner(t: &Tree, paren: Id) -> Option<Id> {
    nth_expr(t, paren, 0)
}

fn useless_parens(t: &Tree, node: Id) -> Option<Report> {
    let diag = match t.kind(node) {
        NODE_ATTRPATH_VALUE => {
            let value = kv_value(t, node)?;
            if t.kind(value) != NODE_PAREN {
                return None;
            }
            let inner = paren_inner(t, value)?;
            let at = t.range(value);
            (at, "Useless parentheses around value in binding", t.text(inner).to_string())
        }
        NODE_LET_IN => {
            let body = let_body(t, node)?;
            if t.kind(body) != NODE_PAREN {
                return None;
            }
            let inner = paren_inner(t, body)?;
            let at = t.range(body);
            (at, "Useless parentheses around body of `let` expression", t.text(inner).to_string())
        }
        NODE_PAREN => {
            let father = t.parent(node)?;
            if matches!(t.kind(father), NODE_ATTRPATH_VALUE | NODE_LET_IN) {
                return None;
            }
            let inner = paren_inner(t, node)?;
            let primitive = match t.kind(inner) {
                NODE_LIST | NODE_PAREN | NODE_STRING | NODE_ATTR_SET | NODE_IDENT => true,
                NODE_SELECT => first_token_of_kind(t, inner, TOKEN_OR).is_none(),
                _ => false,
            };
            if !primitive {
                return None;
            }
            let at = t.range(node);
            (at, "Useless parentheses around primitive expression", t.text(inner).to_string())
        }
        _ => return None,
    };
    Some(report(8).suggest(diag.0, diag.1, diag.0, diag.2))
}

fn lambda_body_of_pattern(t: &Tree, pattern: Id) -> Option<Id> {
    let lambda = t.parent(pattern)?;
    if t.kind(lambda) != NODE_LAMBDA {
        return None;
    }
    nth_expr(t, lambda, 0)
}

fn is_module(t: &Tree, body: Id) -> bool {
    if t.kind(body) != NODE_ATTR_SET {
        return false;
    }
    attrpath_values(t, body).iter().any(|&kv| {
        first_child_of_kind(t, kv, NODE_ATTRPATH).map_or(false, |ap| t.text(ap) == "imports")
    })
}

fn empty_pattern(t: &Tree, node: Id) -> Option<Report> {
    if !children_of_kind(t, node, NODE_PAT_ENTRY).is_empty() {
        return None;
    }
    if first_child_of_kind(t, node, NODE_PAT_BIND).is_some() {
        return None;
    }
    if let Some(body) = lambda_body_of_pattern(t, node) {
        if is_module(t, body) {
            return None;
        }
    }
    let at = t.range(node);
    let message = "This pattern is empty, use `_` instead";
    let replacement = make::ident("_");
    Some(report(10).suggest(at, message, at, replacement))
}

fn redundant_pattern_bind(t: &Tree, node: Id) -> Option<Report> {
    if !children_of_kind(t, node, NODE_PAT_ENTRY).is_empty() {
        return None;
    }
    first_token_of_kind(t, node, TOKEN_ELLIPSIS)?;
    let bind = first_child_of_kind(t, node, NODE_PAT_BIND)?;
    let ident = first_child_of_kind(t, bind, NODE_IDENT)?;
    let at = t.range(node);
    let message = format!("This pattern bind is redundant, use `{}` instead", t.text(ident));
    Some(report(11).suggest(at, message, at, t.text(ident)))
}

fn unquoted_uri(t: &Tree, token: Id) -> Option<Report> {
    let parent = t.parent(token)?;
    let at = t.range(token);
    let replacement = make::quote(t.text(parent));
    let message = "Consider quoting this URI expression";
    Some(report(12).suggest(at, message, at, replacement))
}

fn empty_inherit(t: &Tree, node: Id) -> Option<Report> {
    if first_child_of_kind(t, node, NODE_INHERIT_FROM).is_some() {
        return None;
    }
    if !inherit_attrs(t, node).is_empty() {
        return None;
    }
    let at = t.range(node);
    let replacement_at = match t.prev_sibling_or_token(node) {
        Some(p) if t.kind(p) == TOKEN_WHITESPACE => (t.range(p).0, at.1),
        _ => at,
    };
    let message = "Remove this empty `inherit` statement";
    Some(report(14).suggest(at, message, replacement_at, ""))
}

fn deprecated_to_path(t: &Tree, node: Id) -> Option<Report> {
    let lambda = nth_expr(t, node, 0)?;
    let path = t.text(lambda);
    if path != "builtins.toPath" && path != "toPath" {
        return None;
    }
    let at = t.range(node);
    let message =
        format!("`{}` is deprecated, see `:doc builtins.toPath` within the REPL for more", path);
    Some(report(17).diagnostic(at, message))
}

fn bool_simplification(t: &Tree, node: Id) -> Option<Report> {
    first_token_of_kind(t, node, TOKEN_INVERT)?;
    let value = nth_expr(t, node, 0)?;
    if t.kind(value) != NODE_PAREN {
        return None;
    }
    let inner = paren_inner(t, value)?;
    if t.kind(inner) != NODE_BIN_OP {
        return None;
    }
    if binop_operator(t, inner) != Some(BinOpKind::Equal) {
        return None;
    }
    let at = t.range(node);
    let message = "Try `!=` instead of `!(... == ...)`";
    let lhs = binop_lhs(t, inner)?;
    let rhs = binop_rhs(t, inner)?;
    let replacement = make::binary(t.text(lhs), "!=", t.text(rhs));
    Some(report(18).suggest(at, message, at, replacement))
}

fn useless_has_attr(t: &Tree, node: Id) -> Option<Report> {
    let condition = nth_expr(t, node, 0)?;
    let default = nth_expr(t, node, 2)?;
    if t.kind(condition) != NODE_HAS_ATTR {
        return None;
    }
    let set = nth_expr(t, condition, 0)?;
    let attr_path = first_child_of_kind(t, condition, NODE_ATTRPATH)?;
    let body = nth_expr(t, node, 1)?;
    if t.kind(body) != NODE_SELECT {
        return None;
    }
    let expected = make::select(t.text(set), t.text(attr_path));
    if t.text(body) != expected {
        return None;
    }
    let at = t.range(node);
    let default_text = match t.kind(default) {
        NODE_LIST | NODE_PAREN | NODE_STRING | NODE_ATTR_SET | NODE_IDENT | NODE_SELECT => {
            t.text(default).to_string()
        }
        _ => make::parenthesize(t.text(default)),
    };
    let replacement = make::or_default(t.text(set), t.text(attr_path), &default_text);
    let message = format!("Consider using `{}` instead of this `if` expression", replacement);
    Some(report(19).suggest(at, message, at, replacement))
}

fn repeated_keys(t: &Tree, node: Id) -> Option<Report> {
    let attr_path = first_child_of_kind(t, node, NODE_ATTRPATH)?;
    let components = attrpath_attrs(t, attr_path);
    let first = *components.first()?;
    let first_ident = ident_text(t, first)?;
    if components.len() < 2 {
        return None;
    }
    let parent = t.parent(node)?;
    if t.kind(parent) != NODE_ATTR_SET {
        return None;
    }
    if first_token_of_kind(t, parent, TOKEN_REC).is_some() {
        return None;
    }
    let all: Vec<(Id, Vec<Id>)> = attrpath_values(t, parent)
        .into_iter()
        .filter_map(|kv| {
            let ap = first_child_of_kind(t, kv, NODE_ATTRPATH)?;
            let comps = attrpath_attrs(t, ap);
            let f = *comps.first()?;
            let id = ident_text(t, f)?;
            if id == first_ident {
                Some((ap, comps[1..].to_vec()))
            } else {
                None
            }
        })
        .collect();
    let occurrences: Vec<&(Id, Vec<Id>)> = all.iter().take(3).collect();
    let (first_annotation, first_subkey) = occurrences.first()?;
    if t.range(*first_annotation) != t.range(attr_path) {
        return None;
    }
    let (second_annotation, second_subkey) = occurrences.get(1)?;
    let (third_annotation, third_subkey) = occurrences.get(2)?;

    let subkey = |v: &Vec<Id>| v.iter().map(|&c| t.text(c).to_string()).collect::<Vec<_>>().join(".");

    let first_message = format!("The key `{}` is first assigned here ...", first_ident);
    let second_message = "... repeated here ...";
    let remaining = all.len() - 3;
    let mut third_message = match remaining {
        0 => "... and here.".to_string(),
        1 => "... and here (`1` occurrence omitted).".to_string(),
        n => format!("... and here (`{}` occurrences omitted).", n),
    };
    third_message.push_str(&format!(
        " Try `{} = {{ {}=...; {}=...; {}=...; }}` instead.",
        first_ident,
        subkey(first_subkey),
        subkey(second_subkey),
        subkey(third_subkey)
    ));
    Some(
        report(20)
            .diagnostic(t.range(*first_annotation), first_message)
            .diagnostic(t.range(*second_annotation), second_message)
            .diagnostic(t.range(*third_annotation), third_message),
    )
}

fn is_empty_list(t: &Tree, id: Id) -> bool {
    t.kind(id) == NODE_LIST && expr_children(t, id).is_empty()
}

fn empty_list_concat(t: &Tree, node: Id) -> Option<Report> {
    if binop_operator(t, node)? != BinOpKind::Concat {
        return None;
    }
    let lhs = binop_lhs(t, node)?;
    let rhs = binop_rhs(t, node)?;
    let at = t.range(node);
    let message = "Concatenation with the empty list, `[]`, is a no-op";
    if is_empty_list(t, lhs) {
        Some(report(23).suggest(at, message, at, t.text(rhs)))
    } else if is_empty_list(t, rhs) {
        Some(report(23).suggest(at, message, at, t.text(lhs)))
    } else {
        None
    }
}

/// Run all (enabled) lints over the tree in preorder.
pub fn lint_tree(t: &Tree, disabled: &[String]) -> Vec<Report> {
    let mut out = Vec::new();
    for id in t.preorder_with_tokens(t.root()) {
        for &code in lints_for_kind(t.kind(id)) {
            if disabled.iter().any(|d| d == meta(code).name) {
                continue;
            }
            if let Some(r) = run_lint(code, t, id) {
                out.push(r);
            }
        }
    }
    out
}
EOF"}

actions.command:
cat > /workspace/src/lints.rs <<'EOF'
// The lints themselves.
use crate::ast::*;
use crate::kinds::SyntaxKind::{self, *};
use crate::make;
use crate::report::Report;
use crate::tree::{Id, Tree};

pub struct LintMeta {
    pub name: &'static str,
    pub note: &'static str,
    pub code: u32,
}

pub const LINTS: &[LintMeta] = &[
    LintMeta { name: "bool_comparison", note: "Unnecessary comparison with boolean", code: 1 },
    LintMeta { name: "empty_let_in", note: "Useless let-in expression", code: 2 },
    LintMeta { name: "manual_inherit", note: "Assignment instead of inherit", code: 3 },
    LintMeta { name: "manual_inherit_from", note: "Assignment instead of inherit from", code: 4 },
    LintMeta { name: "legacy_let_syntax", note: "Using undocumented `let` syntax", code: 5 },
    LintMeta { name: "collapsible_let_in", note: "These let-in expressions are collapsible", code: 6 },
    LintMeta { name: "eta_reduction", note: "This function expression is eta reducible", code: 7 },
    LintMeta { name: "useless_parens", note: "These parentheses can be omitted", code: 8 },
    LintMeta { name: "empty_pattern", note: "Found empty pattern in function argument", code: 10 },
    LintMeta {
        name: "redundant_pattern_bind",
        note: "Found redundant pattern bind in function argument",
        code: 11,
    },
    LintMeta { name: "unquoted_uri", note: "Found unquoted URI expression", code: 12 },
    LintMeta { name: "empty_inherit", note: "Found empty inherit statement", code: 14 },
    LintMeta {
        name: "deprecated_to_path",
        note: "Found usage of deprecated builtin toPath",
        code: 17,
    },
    LintMeta {
        name: "bool_simplification",
        note: "This boolean expression can be simplified",
        code: 18,
    },
    LintMeta {
        name: "useless_has_attr",
        note: "This `if` expression can be simplified with `or`",
        code: 19,
    },
    LintMeta { name: "repeated_keys", note: "Avoid repeated keys in attribute sets", code: 20 },
    LintMeta {
        name: "empty_list_concat",
        note: "Unnecessary concatenation with empty list",
        code: 23,
    },
];

fn meta(code: u32) -> &'static LintMeta {
    LINTS.iter().find(|l| l.code == code).unwrap()
}

fn report(code: u32) -> Report {
    Report::new(meta(code).note, code)
}

/// Which lint codes apply to elements of the given kind, in registration order.
pub fn lints_for_kind(kind: SyntaxKind) -> &'static [u32] {
    match kind {
        NODE_BIN_OP => &[1, 23],
        NODE_LET_IN => &[2, 6, 8],
        NODE_ATTRPATH_VALUE => &[3, 4, 8, 20],
        NODE_LEGACY_LET => &[5],
        NODE_LAMBDA => &[7],
        NODE_PAREN => &[8],
        NODE_PATTERN => &[10, 11],
        TOKEN_URI => &[12],
        NODE_INHERIT => &[14],
        NODE_APPLY => &[17],
        NODE_UNARY_OP => &[18],
        NODE_IF_ELSE => &[19],
        _ => &[],
    }
}

pub fn run_lint(code: u32, t: &Tree, id: Id) -> Option<Report> {
    match code {
        1 => bool_comparison(t, id),
        2 => empty_let_in(t, id),
        3 => manual_inherit(t, id),
        4 => manual_inherit_from(t, id),
        5 => legacy_let_syntax(t, id),
        6 => collapsible_let_in(t, id),
        7 => eta_reduction(t, id),
        8 => useless_parens(t, id),
        10 => empty_pattern(t, id),
        11 => redundant_pattern_bind(t, id),
        12 => unquoted_uri(t, id),
        14 => empty_inherit(t, id),
        17 => deprecated_to_path(t, id),
        18 => bool_simplification(t, id),
        19 => useless_has_attr(t, id),
        20 => repeated_keys(t, id),
        23 => empty_list_concat(t, id),
        _ => None,
    }
}

#[derive(PartialEq, Eq, Clone, Copy)]
enum NixBoolean {
    True,
    False,
}

fn boolean_ident(t: &Tree, id: Id) -> Option<NixBoolean> {
    match ident_text(t, id)?.as_str() {
        "true" => Some(NixBoolean::True),
        "false" => Some(NixBoolean::False),
        _ => None,
    }
}

fn bool_comparison(t: &Tree, node: Id) -> Option<Report> {
    let lhs = binop_lhs(t, node)?;
    let rhs = binop_rhs(t, node)?;
    let op = binop_operator(t, node)?;
    if op != BinOpKind::Equal && op != BinOpKind::NotEqual {
        return None;
    }
    let (non_bool_side, bool_side) = if boolean_ident(t, lhs).is_some() {
        (rhs, lhs)
    } else if boolean_ident(t, rhs).is_some() {
        (lhs, rhs)
    } else {
        return None;
    };
    let at = t.range(node);
    let replacement = match (boolean_ident(t, bool_side).unwrap(), op == BinOpKind::Equal) {
        (NixBoolean::True, true) | (NixBoolean::False, false) => t.text(non_bool_side).to_string(),
        _ => match t.kind(non_bool_side) {
            NODE_APPLY | NODE_PAREN | NODE_IDENT | NODE_HAS_ATTR => {
                make::unary_not(t.text(non_bool_side))
            }
            _ => {
                let parens = make::parenthesize(t.text(non_bool_side));
                make::unary_not(&parens)
            }
        },
    };
    let message = format!(
        "Comparing `{}` with boolean literal `{}`",
        t.text(non_bool_side),
        t.text(bool_side)
    );
    Some(report(1).suggest(at, message, at, replacement))
}

fn let_body(t: &Tree, node: Id) -> Option<Id> {
    nth_expr(t, node, 0)
}

fn empty_let_in(t: &Tree, node: Id) -> Option<Report> {
    if !entries(t, node).is_empty() {
        return None;
    }
    let body = let_body(t, node)?;
    let has_comments = t.children_with_tokens(node).iter().any(|&c| t.kind(c) == TOKEN_COMMENT);
    let at = t.range(node);
    let message = "This let-in expression has no entries";
    Some(if has_comments {
        report(2).diagnostic(at, message)
    } else {
        report(2).suggest(at, message, at, t.text(body))
    })
}

fn single_ident_key(t: &Tree, node: Id) -> Option<Id> {
    let attrpath = first_child_of_kind(t, node, NODE_ATTRPATH)?;
    let attrs = attrpath_attrs(t, attrpath);
    if attrs.len() != 1 {
        return None;
    }
    let key = attrs[0];
    if t.kind(key) != NODE_IDENT {
        return None;
    }
    Some(key)
}

fn kv_value(t: &Tree, node: Id) -> Option<Id> {
    nth_expr(t, node, 0)
}

fn manual_inherit(t: &Tree, node: Id) -> Option<Report> {
    let key = single_ident_key(t, node)?;
    let value = kv_value(t, node)?;
    if t.kind(value) != NODE_IDENT {
        return None;
    }
    if t.text(key) != t.text(value) {
        return None;
    }
    let at = t.range(node);
    let replacement = make::inherit_stmt(&[t.text(key)]);
    let message = "This assignment is better written with `inherit`";
    Some(report(3).suggest(at, message, at, replacement))
}

fn manual_inherit_from(t: &Tree, node: Id) -> Option<Report> {
    let key = single_ident_key(t, node)?;
    let value = kv_value(t, node)?;
    if t.kind(value) != NODE_SELECT {
        return None;
    }
    let attrpath = first_child_of_kind(t, value, NODE_ATTRPATH)?;
    let attrs = attrpath_attrs(t, attrpath);
    if attrs.len() != 1 {
        return None;
    }
    let index = attrs[0];
    if t.kind(index) != NODE_IDENT {
        return None;
    }
    if t.text(key) != t.text(index) {
        return None;
    }
    let at = t.range(node);
    let set = nth_expr(t, value, 0)?;
    let replacement = make::inherit_from_stmt(t.text(set), &[t.text(key)]);
    let message = "This assignment is better written with `inherit`";
    Some(report(4).suggest(at, message, at, replacement))
}

fn first_attr_is_ident(t: &Tree, kv: Id, name: &str) -> bool {
    let attrpath = match first_child_of_kind(t, kv, NODE_ATTRPATH) {
        Some(a) => a,
        None => return false,
    };
    match attrpath_attrs(t, attrpath).first() {
        Some(&first) => ident_text(t, first).as_deref() == Some(name),
        None => false,
    }
}

fn legacy_let_syntax(t: &Tree, node: Id) -> Option<Report> {
    if !attrpath_values(t, node).iter().any(|&kv| first_attr_is_ident(t, kv, "body")) {
        return None;
    }
    let inherits: Vec<String> = inherits(t, node).iter().map(|&i| t.text(i).to_string()).collect();
    let entries: Vec<String> = entries(t, node).iter().map(|&i| t.text(i).to_string()).collect();
    let attrset = make::attrset(&inherits, &entries, true);
    let body = make::ident("body");
    let selected = make::select(&attrset, &body);
    let at = t.range(node);
    let message = "Prefer `rec` over undocumented `let` syntax";
    Some(report(5).suggest(at, message, at, selected))
}

fn collapsible_let_in(t: &Tree, node: Id) -> Option<Report> {
    let body = let_body(t, node)?;
    if t.kind(body) != NODE_LET_IN {
        return None;
    }
    let first_annotation = t.range(node);
    let first_message = "This `let in` expression contains a nested `let in` expression";
    let second_annotation = t.range(body);
    let second_message = "This `let in` expression is nested";

    // find `in` token among previous siblings of body (including body itself)
    let mut start = None;
    let mut cur = Some(body);
    while let Some(c) = cur {
        if t.kind(c) == TOKEN_IN {
            start = Some(t.range(c).0);
            break;
        }
        cur = t.prev_sibling_or_token(c);
    }
    let start = start?;
    let end = t
        .preorder_with_tokens(body)
        .into_iter()
        .find(|&e| t.kind(e) == TOKEN_LET)
        .map(|e| t.range(e).1)?;
    Some(report(6).diagnostic(first_annotation, first_message).suggest(
        second_annotation,
        second_message,
        (start, end),
        "",
    ))
}

fn eta_reduction(t: &Tree, node: Id) -> Option<Report> {
    let param = t.children(node).next()?;
    if t.kind(param) != NODE_IDENT_PARAM {
        return None;
    }
    let arg = first_child_of_kind(t, param, NODE_IDENT)?;
    let body = nth_expr(t, node, 0)?;
    if t.kind(body) != NODE_APPLY {
        return None;
    }
    let value = nth_expr(t, body, 1)?;
    if t.kind(value) != NODE_IDENT {
        return None;
    }
    if t.text(arg) != t.text(value) {
        return None;
    }
    let lambda = nth_expr(t, body, 0)?;
    // the function must not mention the argument
    let arg_text = t.text(arg);
    let mentions = t
        .descendants(lambda)
        .into_iter()
        .any(|d| t.kind(d) == NODE_IDENT && t.text(d) == arg_text);
    if mentions {
        return None;
    }
    if t.kind(lambda) != NODE_IDENT {
        return None;
    }
    let at = t.range(node);
    let message = format!("Found eta-reduction: `{}`", t.text(lambda));
    Some(report(7).suggest(at, message, at, t.text(lambda)))
}

fn paren_inner(t: &Tree, paren: Id) -> Option<Id> {
    nth_expr(t, paren, 0)
}

fn useless_parens(t: &Tree, node: Id) -> Option<Report> {
    let diag = match t.kind(node) {
        NODE_ATTRPATH_VALUE => {
            let value = kv_value(t, node)?;
            if t.kind(value) != NODE_PAREN {
                return None;
            }
            let inner = paren_inner(t, value)?;
            let at = t.range(value);
            (at, "Useless parentheses around value in binding", t.text(inner).to_string())
        }
        NODE_LET_IN => {
            let body = let_body(t, node)?;
            if t.kind(body) != NODE_PAREN {
                return None;
            }
            let inner = paren_inner(t, body)?;
            let at = t.range(body);
            (at, "Useless parentheses around body of `let` expression", t.text(inner).to_string())
        }
        NODE_PAREN => {
            let father = t.parent(node)?;
            if matches!(t.kind(father), NODE_ATTRPATH_VALUE | NODE_LET_IN) {
                return None;
            }
            let inner = paren_inner(t, node)?;
            let primitive = match t.kind(inner) {
                NODE_LIST | NODE_PAREN | NODE_STRING | NODE_ATTR_SET | NODE_IDENT => true,
                NODE_SELECT => first_token_of_kind(t, inner, TOKEN_OR).is_none(),
                _ => false,
            };
            if !primitive {
                return None;
            }
            let at = t.range(node);
            (at, "Useless parentheses around primitive expression", t.text(inner).to_string())
        }
        _ => return None,
    };
    Some(report(8).suggest(diag.0, diag.1, diag.0, diag.2))
}

fn lambda_body_of_pattern(t: &Tree, pattern: Id) -> Option<Id> {
    let lambda = t.parent(pattern)?;
    if t.kind(lambda) != NODE_LAMBDA {
        return None;
    }
    nth_expr(t, lambda, 0)
}

fn is_module(t: &Tree, body: Id) -> bool {
    if t.kind(body) != NODE_ATTR_SET {
        return false;
    }
    attrpath_values(t, body).iter().any(|&kv| {
        first_child_of_kind(t, kv, NODE_ATTRPATH).map_or(false, |ap| t.text(ap) == "imports")
    })
}

fn empty_pattern(t: &Tree, node: Id) -> Option<Report> {
    if !children_of_kind(t, node, NODE_PAT_ENTRY).is_empty() {
        return None;
    }
    if first_child_of_kind(t, node, NODE_PAT_BIND).is_some() {
        return None;
    }
    if let Some(body) = lambda_body_of_pattern(t, node) {
        if is_module(t, body) {
            return None;
        }
    }
    let at = t.range(node);
    let message = "This pattern is empty, use `_` instead";
    let replacement = make::ident("_");
    Some(report(10).suggest(at, message, at, replacement))
}

fn redundant_pattern_bind(t: &Tree, node: Id) -> Option<Report> {
    if !children_of_kind(t, node, NODE_PAT_ENTRY).is_empty() {
        return None;
    }
    first_token_of_kind(t, node, TOKEN_ELLIPSIS)?;
    let bind = first_child_of_kind(t, node, NODE_PAT_BIND)?;
    let ident = first_child_of_kind(t, bind, NODE_IDENT)?;
    let at = t.range(node);
    let message = format!("This pattern bind is redundant, use `{}` instead", t.text(ident));
    Some(report(11).suggest(at, message, at, t.text(ident)))
}

fn unquoted_uri(t: &Tree, token: Id) -> Option<Report> {
    let parent = t.parent(token)?;
    let at = t.range(token);
    let replacement = make::quote(t.text(parent));
    let message = "Consider quoting this URI expression";
    Some(report(12).suggest(at, message, at, replacement))
}

fn empty_inherit(t: &Tree, node: Id) -> Option<Report> {
    if first_child_of_kind(t, node, NODE_INHERIT_FROM).is_some() {
        return None;
    }
    if !inherit_attrs(t, node).is_empty() {
        return None;
    }
    let at = t.range(node);
    let replacement_at = match t.prev_sibling_or_token(node) {
        Some(p) if t.kind(p) == TOKEN_WHITESPACE => (t.range(p).0, at.1),
        _ => at,
    };
    let message = "Remove this empty `inherit` statement";
    Some(report(14).suggest(at, message, replacement_at, ""))
}

fn deprecated_to_path(t: &Tree, node: Id) -> Option<Report> {
    let lambda = nth_expr(t, node, 0)?;
    let path = t.text(lambda);
    if path != "builtins.toPath" && path != "toPath" {
        return None;
    }
    let at = t.range(node);
    let message =
        format!("`{}` is deprecated, see `:doc builtins.toPath` within the REPL for more", path);
    Some(report(17).diagnostic(at, message))
}

fn bool_simplification(t: &Tree, node: Id) -> Option<Report> {
    first_token_of_kind(t, node, TOKEN_INVERT)?;
    let value = nth_expr(t, node, 0)?;
    if t.kind(value) != NODE_PAREN {
        return None;
    }
    let inner = paren_inner(t, value)?;
    if t.kind(inner) != NODE_BIN_OP {
        return None;
    }
    if binop_operator(t, inner) != Some(BinOpKind::Equal) {
        return None;
    }
    let at = t.range(node);
    let message = "Try `!=` instead of `!(... == ...)`";
    let lhs = binop_lhs(t, inner)?;
    let rhs = binop_rhs(t, inner)?;
    let replacement = make::binary(t.text(lhs), "!=", t.text(rhs));
    Some(report(18).suggest(at, message, at, replacement))
}

fn useless_has_attr(t: &Tree, node: Id) -> Option<Report> {
    let condition = nth_expr(t, node, 0)?;
    let default = nth_expr(t, node, 2)?;
    if t.kind(condition) != NODE_HAS_ATTR {
        return None;
    }
    let set = nth_expr(t, condition, 0)?;
    let attr_path = first_child_of_kind(t, condition, NODE_ATTRPATH)?;
    let body = nth_expr(t, node, 1)?;
    if t.kind(body) != NODE_SELECT {
        return None;
    }
    let expected = make::select(t.text(set), t.text(attr_path));
    if t.text(body) != expected {
        return None;
    }
    let at = t.range(node);
    let default_text = match t.kind(default) {
        NODE_LIST | NODE_PAREN | NODE_STRING | NODE_ATTR_SET | NODE_IDENT | NODE_SELECT => {
            t.text(default).to_string()
        }
        _ => make::parenthesize(t.text(default)),
    };
    let replacement = make::or_default(t.text(set), t.text(attr_path), &default_text);
    let message = format!("Consider using `{}` instead of this `if` expression", replacement);
    Some(report(19).suggest(at, message, at, replacement))
}

fn repeated_keys(t: &Tree, node: Id) -> Option<Report> {
    let attr_path = first_child_of_kind(t, node, NODE_ATTRPATH)?;
    let components = attrpath_attrs(t, attr_path);
    let first = *components.first()?;
    let first_ident = ident_text(t, first)?;
    if components.len() < 2 {
        return None;
    }
    let parent = t.parent(node)?;
    if t.kind(parent) != NODE_ATTR_SET {
        return None;
    }
    if first_token_of_kind(t, parent, TOKEN_REC).is_some() {
        return None;
    }
    let all: Vec<(Id, Vec<Id>)> = attrpath_values(t, parent)
        .into_iter()
        .filter_map(|kv| {
            let ap = first_child_of_kind(t, kv, NODE_ATTRPATH)?;
            let comps = attrpath_attrs(t, ap);
            let f = *comps.first()?;
            let id = ident_text(t, f)?;
            if id == first_ident {
                Some((ap, comps[1..].to_vec()))
            } else {
                None
            }
        })
        .collect();
    let occurrences: Vec<&(Id, Vec<Id>)> = all.iter().take(3).collect();
    let (first_annotation, first_subkey) = occurrences.first()?;
    if t.range(*first_annotation) != t.range(attr_path) {
        return None;
    }
    let (second_annotation, second_subkey) = occurrences.get(1)?;
    let (third_annotation, third_subkey) = occurrences.get(2)?;

    let subkey = |v: &Vec<Id>| v.iter().map(|&c| t.text(c).to_string()).collect::<Vec<_>>().join(".");

    let first_message = format!("The key `{}` is first assigned here ...", first_ident);
    let second_message = "... repeated here ...";
    let remaining = all.len() - 3;
    let mut third_message = match remaining {
        0 => "... and here.".to_string(),
        1 => "... and here (`1` occurrence omitted).".to_string(),
        n => format!("... and here (`{}` occurrences omitted).", n),
    };
    third_message.push_str(&format!(
        " Try `{} = {{ {}=...; {}=...; {}=...; }}` instead.",
        first_ident,
        subkey(first_subkey),
        subkey(second_subkey),
        subkey(third_subkey)
    ));
    Some(
        report(20)
            .diagnostic(t.range(*first_annotation), first_message)
            .diagnostic(t.range(*second_annotation), second_message)
            .diagnostic(t.range(*third_annotation), third_message),
    )
}

fn is_empty_list(t: &Tree, id: Id) -> bool {
    t.kind(id) == NODE_LIST && expr_children(t, id).is_empty()
}

fn empty_list_concat(t: &Tree, node: Id) -> Option<Report> {
    if binop_operator(t, node)? != BinOpKind::Concat {
        return None;
    }
    let lhs = binop_lhs(t, node)?;
    let rhs = binop_rhs(t, node)?;
    let at = t.range(node);
    let message = "Concatenation with the empty list, `[]`, is a no-op";
    if is_empty_list(t, lhs) {
        Some(report(23).suggest(at, message, at, t.text(rhs)))
    } else if is_empty_list(t, rhs) {
        Some(report(23).suggest(at, message, at, t.text(lhs)))
    } else {
        None
    }
}

/// Run all (enabled) lints over the tree in preorder.
pub fn lint_tree(t: &Tree, disabled: &[String]) -> Vec<Report> {
    let mut out = Vec::new();
    for id in t.preorder_with_tokens(t.root()) {
        for &code in lints_for_kind(t.kind(id)) {
            if disabled.iter().any(|d| d == meta(code).name) {
                continue;
            }
            if let Some(r) = run_lint(code, t, id) {
                out.push(r);
            }
        }
    }
    out
}
