// A renderer for diagnostics producing output in the style of the `ariadne` crate (0.1.x).
use std::fmt::Write;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Red,
    Yellow,
    Magenta,
    Fixed(u8),
}

fn paint(s: &str, color: Option<Color>) -> String {
    match color {
        None => s.to_string(),
        Some(Color::Red) => format!("\x1b[31m{}\x1b[0m", s),
        Some(Color::Yellow) => format!("\x1b[33m{}\x1b[0m", s),
        Some(Color::Magenta) => format!("\x1b[35m{}\x1b[0m", s),
        Some(Color::Fixed(n)) => format!("\x1b[38;5;{}m{}\x1b[0m", n, s),
    }
}

fn paintc(c: char, color: Option<Color>) -> String {
    let mut b = [0u8; 4];
    paint(c.encode_utf8(&mut b), color)
}

const MARGIN: Option<Color> = Some(Color::Fixed(246));
const UNIMPORTANT: Option<Color> = Some(Color::Fixed(249));

mod draw {
    pub const HBAR: char = '─';
    pub const VBAR: char = '│';
    pub const XBAR: char = '┼';
    pub const VBAR_BREAK: char = '·';
    pub const VBAR_GAP: char = '⋮';
    pub const UARROW: char = '▲';
    pub const RARROW: char = '▶';
    pub const LTOP: char = '╭';
    pub const MBOT: char = '┴';
    pub const LBOT: char = '╰';
    pub const RBOT: char = '╯';
    pub const LBOX: char = '[';
    pub const RBOX: char = ']';
    pub const LCROSS: char = '├';
    pub const UNDERBAR: char = '┬';
    pub const UNDERLINE: char = '─';
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ReportKind {
    Error,
    Warning,
}

pub struct Label {
    pub start: usize,
    pub end: usize,
    pub msg: String,
    pub color: Option<Color>,
}

impl Label {
    fn len(&self) -> usize {
        self.end.saturating_sub(self.start)
    }
    fn contains(&self, x: usize) -> bool {
        self.start <= x && x < self.end
    }
    fn last_offset(&self) -> usize {
        self.end.saturating_sub(1).max(self.start)
    }
}

struct Line {
    offset: usize,
    len: usize,
    chars: Vec<char>,
}

impl Line {
    fn span_contains(&self, x: usize) -> bool {
        self.offset <= x && x < self.offset + self.len
    }
    fn span_start(&self) -> usize {
        self.offset
    }
    fn span_end(&self) -> usize {
        self.offset + self.len
    }
}

struct Source {
    lines: Vec<Line>,
    len: usize,
}

impl Source {
    fn from(s: &str) -> Source {
        let mut offset = 0;
        let mut lines = Vec::new();
        for line in s.split('\n') {
            let len = line.chars().count() + 1;
            let chars: Vec<char> = line.trim_end().chars().collect();
            lines.push(Line { offset, len, chars });
            offset += len;
        }
        Source { lines, len: offset }
    }

    fn get_offset_line(&self, offset: usize) -> Option<(usize, usize)> {
        if offset <= self.len {
            let idx = match self.lines.binary_search_by_key(&offset, |l| l.offset) {
                Ok(i) => i,
                Err(i) => i.saturating_sub(1),
            };
            let line = &self.lines[idx];
            Some((idx, offset - line.offset))
        } else {
            None
        }
    }

    fn get_line_range(&self, start: usize, end: usize) -> (usize, usize) {
        let s = self.get_offset_line(start).map_or(0, |(l, _)| l);
        let e = self
            .get_offset_line(end.saturating_sub(1).max(start))
            .map_or(self.lines.len(), |(l, _)| l + 1);
        (s, e)
    }
}

fn char_width(c: char, col: usize) -> (char, usize) {
    match c {
        '\t' => {
            let tab_end = (col / 4 + 1) * 4;
            (' ', tab_end - col)
        }
        c => (c, 1),
    }
}

#[derive(Clone, Copy)]
struct LineLabel {
    col: usize,
    label: usize, // index into labels
    multi: bool,
    draw_msg: bool,
}

pub fn render(
    kind: ReportKind,
    code: &str,
    msg: &str,
    src_name: &str,
    src: &str,
    location: usize,
    labels: &[Label],
) -> String {
    let mut w = String::new();
    let source = Source::from(src);

    // --- Header ---
    let id = format!(
        "[{}] {}:",
        code,
        match kind {
            ReportKind::Error => "Error",
            ReportKind::Warning => "Warning",
        }
    );
    let kind_color = match kind {
        ReportKind::Error => Some(Color::Red),
        ReportKind::Warning => Some(Color::Yellow),
    };
    writeln!(w, "{} {}", paint(&id, kind_color), msg).unwrap();

    if labels.is_empty() {
        return w;
    }

    // source group
    let mut gstart = labels[0].start;
    let mut gend = labels[0].end;
    let mut multiline = Vec::new();
    for l in labels {
        gstart = gstart.min(l.start);
        gend = gend.max(l.end);
        let start_line = source.get_offset_line(l.start).map(|(l, _)| l);
        let end_line = source.get_offset_line(l.last_offset()).map(|(l, _)| l);
        multiline.push(start_line != end_line);
    }
    let (lr_start, lr_end) = source.get_line_range(gstart, gend);

    // line number width
    let line_no_width = {
        let mut count = 0;
        let mut x: u64 = 10;
        while (lr_end as u64) / x != 0 {
            count += 1;
            x = x.saturating_mul(10);
            if count > 20 {
                break;
            }
        }
        count + 1
    };

    let (line_no, col_no) = match source.get_offset_line(location) {
        Some((idx, col)) => (format!("{}", idx + 1), format!("{}", col + 1)),
        None => ("?".to_string(), "?".to_string()),
    };
    writeln!(
        w,
        "{}{}{}{}{}:{}:{}{}",
        " ".repeat(line_no_width + 2),
        paintc(draw::LTOP, MARGIN),
        paintc(draw::HBAR, MARGIN),
        paintc(draw::LBOX, MARGIN),
        src_name,
        line_no,
        col_no,
        paintc(draw::RBOX, MARGIN),
    )
    .unwrap();
    writeln!(w, "{}{}", " ".repeat(line_no_width + 2), paintc(draw::VBAR, MARGIN)).unwrap();

    // multi-line labels sorted by length (descending), stable
    let mut multi_labels: Vec<usize> = (0..labels.len()).filter(|&i| multiline[i]).collect();
    multi_labels.sort_by_key(|&i| -(labels[i].len() as isize));

    for idx in lr_start..lr_end {
        let line = match source.lines.get(idx) {
            Some(l) => l,
            None => continue,
        };

        let margin_label = multi_labels
            .iter()
            .filter_map(|&li| {
                let label = &labels[li];
                let is_start = line.span_contains(label.start);
                let is_end = line.span_contains(label.last_offset());
                if is_start {
                    Some(LineLabel {
                        col: label.start - line.offset,
                        label: li,
                        multi: true,
                        draw_msg: false,
                    })
                } else if is_end {
                    Some(LineLabel {
                        col: label.last_offset() - line.offset,
                        label: li,
                        multi: true,
                        draw_msg: true,
                    })
                } else {
                    None
                }
            })
            .min_by_key(|ll| (ll.col, !labels[ll.label].start));

        let mut line_labels: Vec<LineLabel> = multi_labels
            .iter()
            .filter_map(|&li| {
                let label = &labels[li];
                let is_start = line.span_contains(label.start);
                let is_end = line.span_contains(label.last_offset());
                if is_start && margin_label.map_or(true, |m| m.label != li) {
                    Some(LineLabel {
                        col: label.start - line.offset,
                        label: li,
                        multi: true,
                        draw_msg: false,
                    })
                } else if is_end {
                    Some(LineLabel {
                        col: label.last_offset() - line.offset,
                        label: li,
                        multi: true,
                        draw_msg: true,
                    })
                } else {
                    None
                }
            })
            .collect();

        for (li, label) in labels.iter().enumerate() {
            if label.start >= line.span_start() && label.end <= line.span_end() && !multiline[li] {
                let col = ((label.start + label.end) / 2).max(label.start) - line.offset;
                line_labels.push(LineLabel { col, label: li, multi: false, draw_msg: true });
            }
        }

        if line_labels.is_empty() && margin_label.is_none() {
            continue;
        }

        line_labels.sort_by_key(|ll| (ll.col, !labels[ll.label].start));

        let arrow_end_space = 2;
        let arrow_len = line_labels.iter().fold(0, |l, ll| {
            if ll.multi {
                line.len
            } else {
                l.max(labels[ll.label].end.saturating_sub(line.offset))
            }
        }) + arrow_end_space;

        let get_vbar = |col: usize, row: usize| -> Option<LineLabel> {
            line_labels
                .iter()
                .enumerate()
                .filter(|(_, ll)| margin_label.map_or(true, |m| ll.label != m.label))
                .find(|(j, ll)| ll.col == col && row <= *j)
                .map(|(_, ll)| *ll)
        };

        let get_highlight = |col: usize| -> Option<usize> {
            margin_label
                .iter()
                .map(|ll| ll.label)
                .chain(multi_labels.iter().copied())
                .chain(line_labels.iter().map(|l| l.label))
                .filter(|&l| labels[l].contains(line.offset + col))
                .min_by_key(|&l| labels[l].len())
        };

        let get_underline = |col: usize| -> Option<LineLabel> {
            line_labels
                .iter()
                .filter(|ll| !ll.multi && labels[ll.label].contains(line.offset + col))
                .min_by_key(|ll| labels[ll.label].len())
                .copied()
        };

        // Margin
        write_margin(
            &mut w,
            idx,
            true,
            None,
            &line_labels,
            &margin_label,
            line_no_width,
            &multi_labels,
            labels,
            line,
        );

        // Line
        for (col, &c) in line.chars.iter().enumerate() {
            let color = match get_highlight(col) {
                Some(h) => labels[h].color,
                None => UNIMPORTANT,
            };
            let (c, width) = char_width(c, col);
            if c.is_whitespace() {
                for _ in 0..width {
                    w.push_str(&paintc(c, color));
                }
            } else {
                w.push_str(&paintc(c, color));
            }
        }
        w.push('\n');

        // Arrows
        for row in 0..line_labels.len() {
            let line_label = line_labels[row];

            // Margin alternate
            write_margin(
                &mut w,
                idx,
                false,
                Some((row, false)),
                &line_labels,
                &margin_label,
                line_no_width,
                &multi_labels,
                labels,
                line,
            );
            // Lines alternate
            let mut chars = line.chars.iter();
            for col in 0..arrow_len {
                let width = chars.next().map_or(1, |&c| char_width(c, col).1);
                let vbar = get_vbar(col, row);
                let underline = get_underline(col).filter(|_| row == 0);
                let (c, tail) = if let Some(vbar_ll) = vbar {
                    let color = labels[vbar_ll.label].color;
                    if underline.is_some() {
                        (paintc(draw::UNDERBAR, color), paintc(draw::UNDERLINE, color))
                    } else {
                        (paintc(draw::VBAR, color), paintc(' ', color))
                    }
                } else if let Some(ul) = underline {
                    let color = labels[ul.label].color;
                    (paintc(draw::UNDERLINE, color), paintc(draw::UNDERLINE, color))
                } else {
                    (" ".to_string(), " ".to_string())
                };
                for i in 0..width {
                    if i == 0 {
                        w.push_str(&c);
                    } else {
                        w.push_str(&tail);
                    }
                }
            }
            w.push('\n');

            // Margin
            write_margin(
                &mut w,
                idx,
                false,
                Some((row, true)),
                &line_labels,
                &margin_label,
                line_no_width,
                &multi_labels,
                labels,
                line,
            );
            // Lines
            let ll_color = labels[line_label.label].color;
            let mut chars = line.chars.iter();
            for col in 0..arrow_len {
                let width = chars.next().map_or(1, |&c| char_width(c, col).1);
                let is_hbar = ((col > line_label.col) ^ line_label.multi)
                    || (line_label.draw_msg && col > line_label.col);
                let (c, tail) = if col == line_label.col
                    && margin_label.map_or(true, |m| line_label.label != m.label)
                {
                    let ch = if line_label.multi {
                        if line_label.draw_msg {
                            draw::MBOT
                        } else {
                            draw::RBOT
                        }
                    } else {
                        draw::LBOT
                    };
                    (paintc(ch, ll_color), paintc(draw::HBAR, ll_color))
                } else if let Some(vbar_ll) = get_vbar(col, row) {
                    if is_hbar {
                        (paintc(draw::HBAR, ll_color), paintc(draw::HBAR, ll_color))
                    } else {
                        (paintc(draw::VBAR, labels[vbar_ll.label].color), paintc(' ', ll_color))
                    }
                } else if is_hbar {
                    (paintc(draw::HBAR, ll_color), paintc(draw::HBAR, ll_color))
                } else {
                    (" ".to_string(), " ".to_string())
                };
                if width > 0 {
                    w.push_str(&c);
                }
                for _ in 1..width {
                    w.push_str(&tail);
                }
            }
            if line_label.draw_msg {
                write!(w, " {}", labels[line_label.label].msg).unwrap();
            }
            w.push('\n');
        }
    }

    // Tail of report
    let final_margin = format!("{}{}", draw::HBAR.to_string().repeat(line_no_width + 2), draw::RBOT);
    writeln!(w, "{}", paint(&final_margin, MARGIN)).unwrap();
    w
}

#[allow(clippy::too_many_arguments)]
fn write_margin(
    w: &mut String,
    idx: usize,
    is_line: bool,
    report_row: Option<(usize, bool)>,
    line_labels: &[LineLabel],
    margin_label: &Option<LineLabel>,
    line_no_width: usize,
    multi_labels: &[usize],
    labels: &[Label],
    line: &Line,
) {
    let is_ellipsis = false;
    let line_no_margin = if is_line && !is_ellipsis {
        let line_no = format!("{}", idx + 1);
        format!(
            "{}{} {}",
            " ".repeat(line_no_width.saturating_sub(line_no.chars().count())),
            line_no,
            draw::VBAR
        )
    } else {
        format!(
            "{}{}",
            " ".repeat(line_no_width + 1),
            if is_ellipsis { draw::VBAR_GAP } else { draw::VBAR_BREAK }
        )
    };
    write!(w, " {} ", paint(&line_no_margin, MARGIN)).unwrap();

    let ncols = multi_labels.len() + if multi_labels.is_empty() { 0 } else { 1 };
    for col in 0..ncols {
        let mut corner: Option<(usize, bool)> = None;
        let mut hbar: Option<usize> = None;
        let mut vbar: Option<usize> = None;
        let mut margin_ptr: Option<(LineLabel, bool)> = None;

        let multi_label = multi_labels.get(col).copied();
        let line_start = line.span_start();
        let line_end = line.span_end();

        let upto = (col + 1).min(multi_labels.len());
        for (i, &li) in multi_labels[0..upto].iter().enumerate() {
            let label = &labels[li];
            let margin = margin_label.filter(|m| m.label == li);

            if label.start <= line_end && label.end > line_start {
                let is_parent = i != col;
                let is_start = line.span_contains(label.start);
                let is_end = line.span_contains(label.last_offset());

                if let Some(margin) = margin.filter(|_| is_line) {
                    margin_ptr = Some((margin, is_start));
                } else if !is_start && (!is_end || is_line) {
                    vbar = vbar.or(Some(li).filter(|_| !is_parent));
                } else if let Some((report_row, is_arrow)) = report_row {
                    let label_row = line_labels
                        .iter()
                        .enumerate()
                        .find(|(_, l)| l.label == li)
                        .map_or(0, |(r, _)| r);
                    if report_row == label_row {
                        if let Some(margin) = margin {
                            vbar = Some(margin.label).filter(|_| col == i);
                            if is_start {
                                continue;
                            }
                        }

                        if is_arrow {
                            hbar = Some(li);
                            if !is_parent {
                                corner = Some((li, is_start));
                            }
                        } else if !is_start {
                            vbar = vbar.or(Some(li).filter(|_| !is_parent));
                        }
                    } else {
                        vbar = vbar.or(Some(li)
                            .filter(|_| !is_parent && (is_start ^ (report_row < label_row))));
                    }
                }
            }
        }

        if let (Some((margin, _is_start)), true) = (margin_ptr, is_line) {
            let is_col = multi_label.map_or(false, |ml| ml == margin.label);
            let is_limit = col + 1 == multi_labels.len();
            if !is_col && !is_limit {
                hbar = hbar.or(Some(margin.label));
            }
        }

        let hbar = hbar.filter(|&l| margin_label.map_or(true, |m| m.label != l) || !is_line);

        let (a, b) = if let Some((li, is_start)) = corner {
            let color = labels[li].color;
            (
                paintc(if is_start { draw::LTOP } else { draw::LBOT }, color),
                paintc(draw::HBAR, color),
            )
        } else if let Some(li) = hbar {
            let color = labels[li].color;
            (paintc(draw::HBAR, color), paintc(draw::HBAR, color))
        } else if let Some(li) = vbar {
            let color = labels[li].color;
            (
                paintc(if is_ellipsis { draw::VBAR_GAP } else { draw::VBAR }, color),
                " ".to_string(),
            )
        } else if let (Some((margin, is_start)), true) = (margin_ptr, is_line) {
            let is_col = multi_label.map_or(false, |ml| ml == margin.label);
            let is_limit = col == multi_labels.len();
            let color = labels[margin.label].color;
            (
                paintc(
                    if is_limit {
                        draw::RARROW
                    } else if is_col {
                        if is_start {
                            draw::LTOP
                        } else {
                            draw::LCROSS
                        }
                    } else {
                        draw::HBAR
                    },
                    color,
                ),
                paintc(if !is_limit { draw::HBAR } else { ' ' }, color),
            )
        } else {
            (" ".to_string(), " ".to_string())
        };
        w.push_str(&a);
        w.push_str(&b);
    }
    let _ = (draw::XBAR, draw::UARROW);
}
