    Delete { old_index: usize, old_len: usize, new_index: usize },
    Insert { old_index: usize, new_index: usize, new_len: usize },
    Replace { old_index: usize, old_len: usize, new_index: usize, new_len: usize },
}

impl Op {
    fn old_range(&self) -> (usize, usize) {
        match *self {
            Op::Equal { old_index, len, .. } => (old_index, old_index + len),
            Op::Delete { old_index, old_len, .. } => (old_index, old_index + old_len),
            Op::Insert { old_index, .. } => (old_index, old_index),
            Op::Replace { old_index, old_len, .. } => (old_index, old_index + old_len),
        }
    }
    fn new_range(&self) -> (usize, usize) {
        match *self {
            Op::Equal { new_index, len, .. } => (new_index, new_index + len),
            Op::Delete { new_index, .. } => (new_index, new_index),
            Op::Insert { new_index, new_len, .. } => (new_index, new_index + new_len),
            Op::Replace { new_index, new_len, .. } => (new_index, new_index + new_len),
        }
    }
}

/// Collects ops, merging adjacent deletes/inserts into replaces.
struct Replace {
    ops: Vec<Op>,
    del: Option<(usize, usize, usize)>,
    ins: Option<(usize, usize, usize)>,
    eq: Option<(usize, usize, usize)>,
}

impl Replace {
    fn new() -> Self {
        Replace { ops: Vec::new(), del: None, ins: None, eq: None }
    }
    fn flush_eq(&mut self) {
        if let Some((old_index, new_index, len)) = self.eq.take() {
            self.ops.push(Op::Equal { old_index, new_index, len });
        }
    }
    fn flush_del_ins(&mut self) {
        if let Some((del_old_index, del_old_len, del_new_index)) = self.del.take() {
            if let Some((_, ins_new_index, ins_new_len)) = self.ins.take() {
                self.ops.push(Op::Replace {
                    old_index: del_old_index,
                    old_len: del_old_len,
                    new_index: ins_new_index,
                    new_len: ins_new_len,
                });
            } else {
                self.ops.push(Op::Delete {
                    old_index: del_old_index,
                    old_len: del_old_len,
                    new_index: del_new_index,
                });
            }
        } else if let Some((ins_old_index, ins_new_index, new_len)) = self.ins.take() {
            self.ops.push(Op::Insert { old_index: ins_old_index, new_index: ins_new_index, new_len });
        }
    }
    fn equal(&mut self, old_index: usize, new_index: usize, len: usize) {
        self.flush_del_ins();
        self.eq = if let Some((a, b, l)) = self.eq.take() {
            Some((a, b, l + len))
        } else {
            Some((old_index, new_index, len))
        };
    }
    fn delete(&mut self, old_index: usize, old_len: usize, new_index: usize) {
        self.flush_eq();
        if let Some((a, l, b)) = self.del.take() {
