            Some((a, b, new_len + l))
        } else {
            Some((old_index, new_index, new_len))
        };
    }
    fn finish(mut self) -> Vec<Op> {
        self.flush_eq();
        self.flush_del_ins();
        self.ops
    }
}

struct V {
    offset: isize,
    v: Vec<usize>,
}

impl V {
    fn new(max_d: usize) -> V {
        V { offset: max_d as isize, v: vec![0; 2 * max_d] }
    }
    fn get(&self, k: isize) -> usize {
        self.v[(k + self.offset) as usize]
    }
    fn set(&mut self, k: isize, val: usize) {
        let idx = (k + self.offset) as usize;
        self.v[idx] = val;
    }
}

fn max_d(len1: usize, len2: usize) -> usize {
    (len1 + len2 + 1) / 2 + 1
}

fn common_prefix_len(old: &[&str], os: usize, oe: usize, new: &[&str], ns: usize, ne: usize) -> usize {
    if os >= oe || ns >= ne {
        return 0;
    }
    let mut n = 0;
    while os + n < oe && ns + n < ne && old[os + n] == new[ns + n] {
        n += 1;
    }
    n
}

fn common_suffix_len(old: &[&str], os: usize, oe: usize, new: &[&str], ns: usize, ne: usize) -> usize {
    if os >= oe || ns >= ne {
        return 0;
    }
    let mut n = 0;
    while oe - n > os && ne - n > ns && old[oe - n - 1] == new[ne - n - 1] {
        n += 1;
    }
    n
}

fn find_middle_snake(
    old: &[&str],
    os: usize,
    oe: usize,
    new: &[&str],
    ns: usize,
    ne: usize,
    vf: &mut V,
    vb: &mut V,
) -> Option<(usize, usize)> {
    let n = oe - os;
    let m = ne - ns;
    let delta = n as isize - m as isize;
    let odd = delta & 1 == 1;
    vf.set(1, 0);
    vb.set(1, 0);
    let d_max = max_d(n, m);
    for d in 0..d_max as isize {
        // forward
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vf.get(k - 1) < vf.get(k + 1)) {
                vf.get(k + 1)
            } else {
                vf.get(k - 1) + 1
            };
            let y = (x as isize - k) as usize;
            let (x0, y0) = (x, y);
            if x < n && y < m {
                let advance = common_prefix_len(old, os + x, oe, new, ns + y, ne);
                x += advance;
            }
            vf.set(k, x);
            if odd && (k - delta).abs() <= (d - 1) && vf.get(k) + vb.get(-(k - delta)) >= n {
                return Some((x0 + os, y0 + ns));
            }
            k -= 2;
        }
        // backward
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vb.get(k - 1) < vb.get(k + 1)) {
                vb.get(k + 1)
            } else {
                vb.get(k - 1) + 1
            };
            let mut y = (x as isize - k) as usize;
            if x < n && y < m {
                let advance = common_suffix_len(old, os, os + n - x, new, ns, ns + m - y);
                x += advance;
                y += advance;
            }
            vb.set(k, x);
            if !odd && (k - delta).abs() <= d && vb.get(k) + vf.get(-(k - delta)) >= n {
                return Some((n - x + os, m - y + ns));
            }
            k -= 2;
        }
    }
    None
}

#[allow(clippy::too_many_arguments)]
fn conquer(
    d: &mut Replace,
    old: &[&str],
    mut os: usize,
    mut oe: usize,
    new: &[&str],
    mut ns: usize,
    mut ne: usize,
    vf: &mut V,
    vb: &mut V,
) {
    let cp = common_prefix_len(old, os, oe, new, ns, ne);
    if cp > 0 {
        d.equal(os, ns, cp);
    }
    os += cp;
    ns += cp;
    let cs = common_suffix_len(old, os, oe, new, ns, ne);
    let common_suffix = (oe - cs, ne - cs);
    oe -= cs;
    ne -= cs;

    if os >= oe && ns >= ne {
        // nothing
    } else if ns >= ne {
        d.delete(os, oe - os, ns);
    } else if os >= oe {
        d.insert(os, ns, ne - ns);
    } else if let Some((x, y)) = find_middle_snake(old, os, oe, new, ns, ne, vf, vb) {
        conquer(d, old, os, x, new, ns, y, vf, vb);
        conquer(d, old, x, oe, new, y, ne, vf, vb);
    } else {
        d.delete(os, oe - os, ns);
        d.insert(os, ns, ne - ns);
    }
    if cs > 0 {
        d.equal(common_suffix.0, common_suffix.1, cs);
    }
}

fn diff_ops(old: &[&str], new: &[&str]) -> Vec<Op> {
    let mut d = Replace::new();
    let md = max_d(old.len(), new.len());
    let mut vf = V::new(md);
    let mut vb = V::new(md);
    conquer(&mut d, old, 0, old.len(), new, 0, new.len(), &mut vf, &mut vb);
    d.finish()
}

fn tokenize_lines(s: &str) -> Vec<&str> {
    let bytes = s.as_bytes();
    let mut lines = Vec::new();
    let mut last = 0;
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == b'\r' {
            if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                lines.push(&s[last..i + 2]);
                i += 2;
                last = i;
                continue;
            } else {
                lines.push(&s[last..i + 1]);
                last = i + 1;
            }
        } else if c == b'\n' {
            lines.push(&s[last..i + 1]);
            last = i + 1;
        }
        i += 1;
    }
    if last < s.len() {
        lines.push(&s[last..]);
    }
    lines
}

fn group_diff_ops(mut ops: Vec<Op>, n: usize) -> Vec<Vec<Op>> {
    if ops.is_empty() {
        return vec![];
    }
    let mut pending_group = Vec::new();
    let mut rv = Vec::new();

    if let Some(Op::Equal { old_index, new_index, len }) = ops.first_mut() {
        let offset = (*len).saturating_sub(n);
        *old_index += offset;
        *new_index += offset;
        *len -= offset;
    }
    if let Some(Op::Equal { len, .. }) = ops.last_mut() {
        *len -= (*len).saturating_sub(n);
    }

    for op in ops.into_iter() {
        if let Op::Equal { old_index, new_index, len } = op {
            if len > n * 2 {
                pending_group.push(Op::Equal { old_index, new_index, len: n });
                rv.push(pending_group);
                let offset = len.saturating_sub(n);
                pending_group = vec![Op::Equal {
                    old_index: old_index + offset,
                    new_index: new_index + offset,
                    len: len - offset,
                }];
                continue;
            }
        }
        pending_group.push(op);
    }

    match &pending_group[..] {
        [] | [Op::Equal { .. }] => {}
        _ => rv.push(pending_group),
    }
    rv
}

fn fmt_range(start: usize, end: usize) -> String {
    let mut beginning = start + 1;
    let len = end.saturating_sub(start);
    if len == 1 {
        format!("{}", beginning)
    } else {
        if len == 0 {
            beginning -= 1;
        }
        format!("{},{}", beginning, len)
    }
}

fn push_change(out: &mut String, tag: char, value: &str) {
    out.push(tag);
    out.push_str(value);
    if !(value.ends_with('\n') || value.ends_with('\r')) {
        out.push_str("\n\\ No newline at end of file\n");
    }
}

/// Produce a unified diff (context radius 4) between `old` and `new`.
pub fn unified_diff(old: &str, new: &str, old_name: &str, new_name: &str) -> String {
    let old_lines = tokenize_lines(old);
    let new_lines = tokenize_lines(new);
    let ops = diff_ops(&old_lines, &new_lines);
    let groups = group_diff_ops(ops, 4);
    let mut out = String::new();
    let mut header = true;
    for group in groups {
        if group.is_empty() {
            continue;
        }
        if header {
            out.push_str(&format!("--- {}\n+++ {}\n", old_name, new_name));
            header = false;
        }
        let first = group.first().unwrap();
        let last = group.last().unwrap();
        out.push_str(&format!(
            "@@ -{} +{} @@\n",
            fmt_range(first.old_range().0, last.old_range().1),
            fmt_range(first.new_range().0, last.new_range().1)
        ));
        for op in &group {
            match *op {
                Op::Equal { old_index, len, .. } => {
                    for l in &old_lines[old_index..old_index + len] {
                        push_change(&mut out, ' ', l);
                    }
                }
                Op::Delete { old_index, old_len, .. } => {
                    for l in &old_lines[old_index..old_index + old_len] {
                        push_change(&mut out, '-', l);
                    }
                }
                Op::Insert { new_index, new_len, .. } => {
                    for l in &new_lines[new_index..new_index + new_len] {
                        push_change(&mut out, '+', l);
                    }
                }
                Op::Replace { old_index, old_len, new_index, new_len } => {
                    for l in &old_lines[old_index..old_index + old_len] {
                        push_change(&mut out, '-', l);
                    }
                    for l in &new_lines[new_index..new_index + new_len] {
                        push_change(&mut out, '+', l);
                    }
                }
            }
        }
    }
    out
}
EOF"}

