struct Parser<'a> {
    tokens: Tokenizer<'a>,
    input: &'a str,
}

pub struct Document {
    /// top-level key/values (only root table), with value start offsets
    pub root: Vec<(String, usize, Value)>,
}

impl<'a> Parser<'a> {
    fn peek(&mut self) -> Res<Option<(usize, Token<'a>)>> {
        let save = self.tokens.pos;
        let r = self.tokens.next();
        self.tokens.pos = save;
        r
    }
    fn next(&mut self) -> Res<Option<(usize, Token<'a>)>> {
        self.tokens.next()
    }
    fn eat(&mut self, t: Token<'a>) -> Res<bool> {
        match self.peek()? {
            Some((_, ref tok)) if *tok == t => {
                self.next()?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }
    fn eat_whitespace(&mut self) -> Res<()> {
        while self.eat(Token::Whitespace)? {}
        Ok(())
    }
    fn eat_comment(&mut self) -> Res<bool> {
        if !self.eat(Token::Comment)? {
            return Ok(false);
        }
        self.eat_newline_or_eof()?;
        Ok(true)
    }
    fn eat_newline_or_eof(&mut self) -> Res<()> {
        let current = self.tokens.current();
        match self.next()? {
            None | Some((_, Token::Newline)) => Ok(()),
            Some((_, other)) => {
                Err(err(format!("expected newline, found {}", other.describe()), current))
            }
        }
    }
    fn expect(&mut self, expected: Token<'a>) -> Res<usize> {
        let current = self.tokens.current();
        match self.next()? {
            Some((start, found)) => {
                if found == expected {
                    Ok(start)
                } else {
                    Err(err(
                        format!("expected {}, found {}", expected.describe(), found.describe()),
                        current,
                    ))
                }
            }
            None => Err(err(
                format!("expected {}, found eof", expected.describe()),
                self.input.len(),
            )),
        }
    }
    fn table_key(&mut self) -> Res<String> {
        let current = self.tokens.current();
        match self.next()? {
            Some((_, Token::Keylike(k))) => Ok(k.to_string()),
            Some((start, Token::Str { val, multiline })) => {
                if multiline {
                    return Err(err("multiline strings are not allowed for key", start));
                }
                Ok(val)
            }
            Some((_, other)) => {
                Err(err(format!("expected a table key, found {}", other.describe()), current))
            }
            None => Err(err("expected a table key, found eof", self.input.len())),
        }
    }
    fn dotted_key(&mut self) -> Res<Vec<String>> {
        let mut result = vec![self.table_key()?];
        self.eat_whitespace()?;
        while self.eat(Token::Period)? {
            self.eat_whitespace()?;
            result.push(self.table_key()?);
            self.eat_whitespace()?;
        }
        Ok(result)
    }

    fn value(&mut self) -> Res<(usize, Value)> {
        let at = self.tokens.current();
        match self.next()? {
            Some((start, Token::Str { val, .. })) => Ok((start, Value::Str(val))),
            Some((start, Token::Keylike("true"))) => Ok((start, Value::Bool(true))),
            Some((start, Token::Keylike("false"))) => Ok((start, Value::Bool(false))),
            Some((start, Token::Keylike(key))) => self.number_or_date(start, key),
            Some((start, Token::Plus)) => {
                let s2 = self.tokens.current();
                match self.next()? {
                    Some((_, Token::Keylike(key))) => {
                        let (_, v) = self.number_or_date(s2, key)?;
                        Ok((start, v))
                    }
                    _ => Err(err("invalid number", start)),
                }
            }
            Some((start, Token::LeftBrace)) => {
                self.inline_table()?;
                Ok((start, Value::Table))
            }
            Some((start, Token::LeftBracket)) => {
                let (items, _) = self.array()?;
                Ok((start, Value::Array(items, start)))
            }
            Some((_, token)) => {
                Err(err(format!("expected a value, found {}", token.describe()), at))
            }
            None => Err(err("unexpected eof encountered", self.input.len())),
        }
    }

    fn number_or_date(&mut self, start: usize, s: &'a str) -> Res<(usize, Value)> {
        // dates
        let looks_like_date = s.len() >= 5
            && s.as_bytes()[..4].iter().all(|b| b.is_ascii_digit())
            && s.as_bytes()[4] == b'-';
        let looks_like_time = s.len() >= 3
            && s.as_bytes()[..2].iter().all(|b| b.is_ascii_digit())
            && s.as_bytes()[2] == b':';
