                        self.next()?;
                        match self.peek()? {
                            Some((_, Token::Keylike(k)))
                                if k.len() >= 3 && k.as_bytes()[2] == b':' =>
                            {
                                self.next()?;
                            }
                            _ => {
                                self.tokens.pos = save;
                                break;
                            }
                        }
                    }
                    _ => break,
                }
            }
            return Ok((start, Value::Datetime));
        }
        if self.eat(Token::Period)? {
            let at = self.tokens.current();
            match self.next()? {
                Some((_, Token::Keylike(after))) => {
                    let text = format!("{}.{}", s, after);
                    match parse_float(&text) {
                        Some(f) => Ok((start, Value::Float(f, text))),
                        None => Err(err("invalid number", start)),
                    }
                }
                _ => Err(err("invalid number", at)),
            }
        } else if s == "inf" || s == "-inf" || s == "nan" || s == "-nan" {
            Ok((start, Value::Float(0.0, s.to_string())))
        } else if s.contains('e') || s.contains('E') {
            match parse_float(s) {
                Some(f) => Ok((start, Value::Float(f, s.to_string()))),
                None => Err(err("invalid number", start)),
            }
        } else {
            match parse_integer(s) {
                Some(i) => Ok((start, Value::Int(i))),
                None => {
                    let first = s.chars().next().unwrap_or(' ');
                    if first.is_ascii_digit() || first == '-' {
                        Err(err("invalid number", start))
                    } else {
                        Err(err("invalid TOML value, did you mean to use a quoted string?", start))
                    }
                }
            }
        }
    }

    fn inline_table(&mut self) -> Res<()> {
        self.eat_whitespace()?;
        if self.eat(Token::RightBrace)? {
            return Ok(());
        }
        loop {
            let _key = self.dotted_key()?;
            self.eat_whitespace()?;
            self.expect(Token::Equals)?;
            self.eat_whitespace()?;
            self.value()?;
            self.eat_whitespace()?;
            if self.eat(Token::RightBrace)? {
                return Ok(());
            }
            self.expect(Token::Comma)?;
            self.eat_whitespace()?;
        }
    }

    fn array(&mut self) -> Res<(Vec<(usize, Value)>, usize)> {
        let mut ret = Vec::new();
        loop {
            self.intermediate()?;
            if self.eat(Token::RightBracket)? {
                return Ok((ret, 0));
            }
            let v = self.value()?;
            ret.push(v);
            self.intermediate()?;
            if !self.eat(Token::Comma)? {
                break;
            }
        }
        self.intermediate()?;
        self.expect(Token::RightBracket)?;
        Ok((ret, 0))
    }

    fn intermediate(&mut self) -> Res<()> {
        loop {
            self.eat_whitespace()?;
            if !self.eat(Token::Newline)? && !self.eat_comment()? {
                break;
            }
        }
        Ok(())
    }

    fn parse(&mut self) -> Res<Document> {
        let mut doc = Document { root: Vec::new() };
        let mut in_root = true;
        let mut tables: Vec<Vec<String>> = Vec::new();
        loop {
            loop {
                self.eat_whitespace()?;
                if self.eat_comment()? {
                    continue;
                }
                if self.eat(Token::Newline)? {
                    continue;
                }
                break;
            }
            match self.peek()? {
                None => break,
                Some((hstart, Token::LeftBracket)) => {
                    self.next()?;
                    let array = self.eat(Token::LeftBracket)?;
                    self.eat_whitespace()?;
                    let key = self.dotted_key()?;
                    self.expect(Token::RightBracket)?;
                    if array {
                        self.expect(Token::RightBracket)?;
                    }
                    self.eat_whitespace()?;
                    if !self.eat_comment()? {
                        self.eat_newline_or_eof()?;
                    }
                    if !array {
                        if tables.contains(&key) {
                            let mut e = err(
                                format!("redefinition of table `{}`", key.join(".")),
                                hstart,
                            );
                            e.key = key.clone();
                            return Err(e);
                        }
                        tables.push(key);
                    }
                    in_root = false;
                }
                Some(_) => {
                    let key = self.dotted_key()?;
                    self.eat_whitespace()?;
                    self.expect(Token::Equals)?;
                    self.eat_whitespace()?;
                    let (start, value) = self.value()?;
                    self.eat_whitespace()?;
                    if !self.eat_comment()? {
                        self.eat_newline_or_eof()?;
                    }
                    if in_root && key.len() == 1 {
                        doc.root.push((key[0].clone(), start, value));
                    }
                }
            }
        }
        Ok(doc)
    }
}

fn parse_integer(s: &str) -> Option<i64> {
    let (neg, digits) = if let Some(r) = s.strip_prefix('-') { (true, r) } else { (false, s) };
    let (radix, digits) = if let Some(r) = digits.strip_prefix("0x") {
        (16, r)
    } else if let Some(r) = digits.strip_prefix("0o") {
        (8, r)
    } else if let Some(r) = digits.strip_prefix("0b") {
        (2, r)
    } else {
        (10, digits)
    };
    if digits.is_empty() {
        return None;
    }
    if radix == 10 && digits.len() > 1 && digits.starts_with('0') {
        return None;
    }
    if digits.starts_with('_') || digits.ends_with('_') || digits.contains("__") {
        return None;
    }
    let clean: String = digits.chars().filter(|&c| c != '_').collect();
    let v = i64::from_str_radix(&clean, radix).ok()?;
    Some(if neg { -v } else { v })
}

fn parse_float(s: &str) -> Option<f64> {
    if s.contains("__") || s.ends_with('_') || s.starts_with('_') || s.contains("_.") || s.contains("._") {
        return None;
    }
    let clean: String = s.chars().filter(|&c| c != '_').collect();
    // reject leading zeros like 01.5
    let body = clean.trim_start_matches('-');
    if body.len() > 1 && body.starts_with('0') && body.as_bytes()[1].is_ascii_digit() {
        return None;
    }
    if body.ends_with('.') || body.starts_with('.') {
        return None;
    }
    clean.parse::<f64>().ok()
}

pub fn parse(input: &str) -> Result<Document, Error> {
    let mut p = Parser { tokens: Tokenizer { input, pos: 0 }, input };
    p.parse()
}

pub fn to_linecol(input: &str, offset: usize) -> (usize, usize) {
    let mut cur = 0;
    for (i, line) in input.split_terminator('\n').enumerate() {
        if cur + line.len() + 1 > offset {
            return (i, offset - cur);
        }
        cur += line.len() + 1;
    }
    (input.lines().count(), 0)
}

impl Error {
    pub fn display(&self, input: &str) -> String {
        let mut s = self.msg.clone();
        if !self.key.is_empty() {
            s.push_str(&format!(" for key `{}`", self.key.join(".")));
        }
        if let Some(at) = self.at {
            let (line, col) = to_linecol(input, at);
            s.push_str(&format!(" at line {} column {}", line + 1, col + 1));
        }
        s
    }
}

fn describe_value(v: &Value) -> String {
    match v {
        Value::Str(s) => format!("invalid type: string {:?}", s),
        Value::Int(i) => format!("invalid type: integer `{}`", i),
        Value::Float(f, text) => {
            let _ = text;
            format!("invalid type: floating point `{}`", fmt_float(*f))
        }
        Value::Bool(b) => format!("invalid type: boolean `{}`", b),
        Value::Datetime | Value::Table => "invalid type: map".to_string(),
        Value::Array(..) => "invalid type: sequence".to_string(),
    }
}

fn fmt_float(f: f64) -> String {
    if f.is_finite() && f.fract() == 0.0 && f.abs() < 1e16 {
        format!("{:.1}", f)
    } else {
        format!("{}", f)
    }
}

/// Deserialize a `Vec<String>` field from a value.
pub fn expect_string_list(key: &str, start: usize, v: &Value) -> Result<Vec<String>, Error> {
    match v {
        Value::Array(items, _) => {
            let mut out = Vec::new();
            for (istart, item) in items {
                match item {
                    Value::Str(s) => out.push(s.clone()),
                    Value::Array(..) => {
                        return Err(Error {
                            msg: format!("{}, expected a string", describe_value(item)),
                            at: Some(0),
                            key: vec![key.to_string()],
                        })
                    }
                    other => {
                        return Err(Error {
                            msg: format!("{}, expected a string", describe_value(other)),
                            at: Some(*istart),
                            key: vec![key.to_string()],
                        })
                    }
                }
            }
            Ok(out)
        }
        other => Err(Error {
            msg: format!("{}, expected a sequence", describe_value(other)),
            at: Some(start),
            key: vec![key.to_string()],
        }),
    }
}
EOF"}

