// A small TOML parser, sufficient for statix.toml, producing errors in the
// style of the `toml` crate (0.5).

#[derive(Debug, Clone)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64, String),
    Bool(bool),
    Datetime,
    Array(Vec<(usize, Value)>, usize),
    Table,
}

#[derive(Debug, Clone, PartialEq)]
enum Token<'a> {
    Whitespace,
    Newline,
    Comment,
    Equals,
    Period,
    Comma,
    Colon,
    Plus,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(&'a str),
    Str { val: String, multiline: bool },
}

impl<'a> Token<'a> {
    fn describe(&self) -> &'static str {
        match self {
            Token::Keylike(_) => "an identifier",
            Token::Equals => "an equals",
            Token::Period => "a period",
            Token::Comment => "a comment",
            Token::Newline => "a newline",
            Token::Whitespace => "whitespace",
            Token::Comma => "a comma",
            Token::RightBrace => "a right brace",
            Token::LeftBrace => "a left brace",
            Token::RightBracket => "a right bracket",
            Token::LeftBracket => "a left bracket",
            Token::Str { multiline, .. } => {
                if *multiline {
                    "a multiline string"
                } else {
                    "a string"
                }
            }
            Token::Colon => "a colon",
            Token::Plus => "a plus",
        }
    }
}

pub struct Error {
    pub msg: String,
    pub at: Option<usize>,
    pub key: Vec<String>,
}

type Res<T> = Result<T, Error>;

fn err(msg: impl Into<String>, at: usize) -> Error {
    Error { msg: msg.into(), at: Some(at), key: Vec::new() }
}

struct Tokenizer<'a> {
    input: &'a str,
    pos: usize,
}

fn is_keylike(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '-' || c == '_'
}

impl<'a> Tokenizer<'a> {
    fn peek_char(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn current(&self) -> usize {
        self.pos
    }

    /// Returns (start, token).
    fn next(&mut self) -> Res<Option<(usize, Token<'a>)>> {
        let start = self.pos;
        let c = match self.peek_char() {
            None => return Ok(None),
            Some(c) => c,
        };
        let tok = match c {
            '\n' => {
                self.pos += 1;
                Token::Newline
            }
            '\r' => {
                if self.input[self.pos + 1..].starts_with('\n') {
                    self.pos += 2;
                    Token::Newline
                } else {
                    return Err(err("unexpected character found: `\\r`", start));
                }
            }
            ' ' | '\t' => {
                while matches!(self.peek_char(), Some(' ') | Some('\t')) {
                    self.pos += 1;
                }
                Token::Whitespace
            }
            '#' => {
                self.pos += 1;
                while let Some(c) = self.peek_char() {
                    if c == '\n' {
                        break;
                    }
                    if c != '\t' && (c as u32) < 0x20 || c == '\u{7f}' {
                        if c == '\r' {
                            break;
                        }
                    }
                    self.pos += c.len_utf8();
                }
                Token::Comment
            }
            '=' => {
                self.pos += 1;
                Token::Equals
            }
            '.' => {
                self.pos += 1;
                Token::Period
            }
            ',' => {
                self.pos += 1;
                Token::Comma
            }
            ':' => {
                self.pos += 1;
                Token::Colon
            }
            '+' => {
                self.pos += 1;
                Token::Plus
            }
            '{' => {
                self.pos += 1;
                Token::LeftBrace
            }
            '}' => {
                self.pos += 1;
                Token::RightBrace
            }
            '[' => {
                self.pos += 1;
                Token::LeftBracket
            }
            ']' => {
                self.pos += 1;
                Token::RightBracket
            }
            '"' => self.basic_string(start)?,
            '\'' => self.literal_string(start)?,
            c if is_keylike(c) => {
                while self.peek_char().map_or(false, is_keylike) {
                    self.pos += 1;
                }
                Token::Keylike(&self.input[start..self.pos])
            }
            c => {
                return Err(err(format!("unexpected character found: `{}`", c.escape_debug()), start))
            }
        };
        Ok(Some((start, tok)))
    }

    fn literal_string(&mut self, start: usize) -> Res<Token<'a>> {
        self.pos += 1;
        let multiline = self.input[self.pos..].starts_with("''");
        if multiline {
            self.pos += 2;
            if self.input[self.pos..].starts_with('\n') {
                self.pos += 1;
            } else if self.input[self.pos..].starts_with("\r\n") {
                self.pos += 2;
            }
        }
        let mut val = String::new();
        loop {
            let c = match self.peek_char() {
                None => return Err(err("unterminated string", start)),
                Some(c) => c,
            };
            let at = self.pos;
            self.pos += c.len_utf8();
            match c {
                '\'' => {
                    if multiline {
                        if self.input[self.pos..].starts_with("''") {
                            self.pos += 2;
                            return Ok(Token::Str { val, multiline: true });
                        }
                        val.push(c);
                    } else {
                        return Ok(Token::Str { val, multiline: false });
                    }
                }
                '\n' if multiline => val.push('\n'),
                '\r' if multiline && self.input[self.pos..].starts_with('\n') => {}
                '\n' => return Err(err("newline in string found", at)),
                c if c == '\t' || (c as u32) >= 0x20 && c != '\u{7f}' => val.push(c),
                c => {
                    return Err(err(
                        format!("invalid character in string: `{}`", c.escape_debug()),
                        at,
                    ))
                }
            }
        }
    }

    fn basic_string(&mut self, start: usize) -> Res<Token<'a>> {
        self.pos += 1;
        let multiline = self.input[self.pos..].starts_with("\"\"");
        if multiline {
            self.pos += 2;
            if self.input[self.pos..].starts_with('\n') {
                self.pos += 1;
            } else if self.input[self.pos..].starts_with("\r\n") {
                self.pos += 2;
            }
        }
        let mut val = String::new();
        loop {
            let c = match self.peek_char() {
                None => return Err(err("unterminated string", start)),
                Some(c) => c,
            };
            let at = self.pos;
            self.pos += c.len_utf8();
            match c {
                '"' => {
                    if multiline {
                        if self.input[self.pos..].starts_with("\"\"") {
                            self.pos += 2;
                            return Ok(Token::Str { val, multiline: true });
                        }
                        val.push(c);
                    } else {
                        return Ok(Token::Str { val, multiline: false });
                    }
                }
                '\\' => {
                    let e = match self.peek_char() {
                        None => return Err(err("unterminated string", start)),
                        Some(e) => e,
                    };
                    let eat = self.pos;
                    self.pos += e.len_utf8();
                    match e {
                        '"' => val.push('"'),
                        '\\' => val.push('\\'),
                        'b' => val.push('\u{8}'),
                        'f' => val.push('\u{c}'),
                        'n' => val.push('\n'),
                        'r' => val.push('\r'),
                        't' => val.push('\t'),
                        'u' | 'U' => {
                            let len = if e == 'u' { 4 } else { 8 };
                            let mut v: u32 = 0;
                            for _ in 0..len {
                                let h = match self.peek_char() {
                                    None => return Err(err("unterminated string", start)),
                                    Some(h) => h,
                                };
                                let hat = self.pos;
                                match h.to_digit(16) {
                                    Some(d) => v = v * 16 + d,
                                    None => {
                                        return Err(err(
                                            format!(
                                                "invalid hex escape character in string: `{}`",
                                                h.escape_debug()
                                            ),
                                            hat,
                                        ))
                                    }
                                }
                                self.pos += h.len_utf8();
                            }
                            match char::from_u32(v) {
                                Some(c) => val.push(c),
                                None => {
                                    return Err(err(
                                        format!("invalid escape value: `{}`", v),
                                        eat - 1,
                                    ))
                                }
                            }
                        }
                        ' ' | '\t' | '\n' | '\r' if multiline => {
                            // line ending backslash
                            let mut p = self.pos - e.len_utf8();
                            let rest = &self.input[p..];
                            let trimmed = rest.trim_start_matches(|c| c == ' ' || c == '\t');
                            if !(trimmed.starts_with('\n') || trimmed.starts_with("\r\n")) {
                                return Err(err(
                                    format!(
                                        "invalid escape character in string: `{}`",
                                        e.escape_debug()
                                    ),
                                    eat,
                                ));
                            }
                            p += rest.len() - trimmed.len();
                            let rest = &self.input[p..];
                            let trimmed = rest.trim_start_matches(|c: char| c.is_whitespace());
                            p += rest.len() - trimmed.len();
                            self.pos = p;
                        }
                        e => {
                            return Err(err(
                                format!("invalid escape character in string: `{}`", e.escape_debug()),
                                eat,
                            ))
                        }
                    }
                }
                '\n' if multiline => val.push('\n'),
                '\r' if multiline && self.input[self.pos..].starts_with('\n') => {}
                '\n' => return Err(err("newline in string found", at)),
                c if c == '\t' || (c as u32) >= 0x20 && c != '\u{7f}' => val.push(c),
                c => {
                    return Err(err(
                        format!("invalid character in string: `{}`", c.escape_debug()),
                        at,
                    ))
                }
            }
        }
    }
}

struct Parser<'a> {
    tokens: Tokenizer<'a>,
    input: &'a str,
}

pub struct Document {
    /// top-level key/values (only root table), with value start offsets
    pub root: Vec<(String, usize, Value)>,
}

impl<'a> Parser<'a> {
    fn peek(&mut self) -> Res<Option<(usize, Token<'a>)>> {
        let save = self.tokens.pos;
        let r = self.tokens.next();
        self.tokens.pos = save;
        r
    }
    fn next(&mut self) -> Res<Option<(usize, Token<'a>)>> {
        self.tokens.next()
    }
    fn eat(&mut self, t: Token<'a>) -> Res<bool> {
        match self.peek()? {
            Some((_, ref tok)) if *tok == t => {
                self.next()?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }
    fn eat_whitespace(&mut self) -> Res<()> {
        while self.eat(Token::Whitespace)? {}
        Ok(())
    }
    fn eat_comment(&mut self) -> Res<bool> {
        if !self.eat(Token::Comment)? {
            return Ok(false);
        }
        self.eat_newline_or_eof()?;
        Ok(true)
    }
    fn eat_newline_or_eof(&mut self) -> Res<()> {
        let current = self.tokens.current();
        match self.next()? {
            None | Some((_, Token::Newline)) => Ok(()),
            Some((_, other)) => {
                Err(err(format!("expected newline, found {}", other.describe()), current))
            }
        }
    }
    fn expect(&mut self, expected: Token<'a>) -> Res<usize> {
        let current = self.tokens.current();
        match self.next()? {
            Some((start, found)) => {
                if found == expected {
                    Ok(start)
                } else {
                    Err(err(
                        format!("expected {}, found {}", expected.describe(), found.describe()),
                        current,
                    ))
                }
            }
            None => Err(err(
                format!("expected {}, found eof", expected.describe()),
                self.input.len(),
            )),
        }
    }
    fn table_key(&mut self) -> Res<String> {
        let current = self.tokens.current();
        match self.next()? {
            Some((_, Token::Keylike(k))) => Ok(k.to_string()),
            Some((start, Token::Str { val, multiline })) => {
                if multiline {
                    return Err(err("multiline strings are not allowed for key", start));
                }
                Ok(val)
            }
            Some((_, other)) => {
                Err(err(format!("expected a table key, found {}", other.describe()), current))
            }
            None => Err(err("expected a table key, found eof", self.input.len())),
        }
    }
    fn dotted_key(&mut self) -> Res<Vec<String>> {
        let mut result = vec![self.table_key()?];
        self.eat_whitespace()?;
        while self.eat(Token::Period)? {
            self.eat_whitespace()?;
            result.push(self.table_key()?);
            self.eat_whitespace()?;
        }
        Ok(result)
    }

    fn value(&mut self) -> Res<(usize, Value)> {
        let at = self.tokens.current();
        match self.next()? {
            Some((start, Token::Str { val, .. })) => Ok((start, Value::Str(val))),
            Some((start, Token::Keylike("true"))) => Ok((start, Value::Bool(true))),
            Some((start, Token::Keylike("false"))) => Ok((start, Value::Bool(false))),
            Some((start, Token::Keylike(key))) => self.number_or_date(start, key),
            Some((start, Token::Plus)) => {
                let s2 = self.tokens.current();
                match self.next()? {
                    Some((_, Token::Keylike(key))) => {
                        let (_, v) = self.number_or_date(s2, key)?;
                        Ok((start, v))
                    }
                    _ => Err(err("invalid number", start)),
                }
            }
            Some((start, Token::LeftBrace)) => {
                self.inline_table()?;
                Ok((start, Value::Table))
            }
            Some((start, Token::LeftBracket)) => {
                let (items, _) = self.array()?;
                Ok((start, Value::Array(items, start)))
            }
            Some((_, token)) => {
                Err(err(format!("expected a value, found {}", token.describe()), at))
            }
            None => Err(err("unexpected eof encountered", self.input.len())),
        }
    }

    fn number_or_date(&mut self, start: usize, s: &'a str) -> Res<(usize, Value)> {
        // dates
        let looks_like_date = s.len() >= 5
            && s.as_bytes()[..4].iter().all(|b| b.is_ascii_digit())
            && s.as_bytes()[4] == b'-';
        let looks_like_time = s.len() >= 3
            && s.as_bytes()[..2].iter().all(|b| b.is_ascii_digit())
            && s.as_bytes()[2] == b':';
        if looks_like_date || looks_like_time {
            // consume the rest of a datetime loosely
            loop {
                match self.peek()? {
                    Some((_, Token::Colon)) | Some((_, Token::Period)) | Some((_, Token::Plus)) => {
                        self.next()?;
                        if let Some((_, Token::Keylike(_))) = self.peek()? {
                            self.next()?;
                        }
                    }
                    Some((_, Token::Whitespace)) => {
                        // "1979-05-27 07:32:00"
                        let save = self.tokens.pos;
                        self.next()?;
                        match self.peek()? {
                            Some((_, Token::Keylike(k)))
                                if k.len() >= 3 && k.as_bytes()[2] == b':' =>
                            {
                                self.next()?;
                            }
                            _ => {
                                self.tokens.pos = save;
                                break;
                            }
                        }
                    }
                    _ => break,
                }
            }
            return Ok((start, Value::Datetime));
        }
        if self.eat(Token::Period)? {
            let at = self.tokens.current();
            match self.next()? {
                Some((_, Token::Keylike(after))) => {
                    let text = format!("{}.{}", s, after);
                    match parse_float(&text) {
                        Some(f) => Ok((start, Value::Float(f, text))),
                        None => Err(err("invalid number", start)),
                    }
                }
                _ => Err(err("invalid number", at)),
            }
        } else if s == "inf" || s == "-inf" || s == "nan" || s == "-nan" {
            Ok((start, Value::Float(0.0, s.to_string())))
        } else if s.contains('e') || s.contains('E') {
            match parse_float(s) {
                Some(f) => Ok((start, Value::Float(f, s.to_string()))),
                None => Err(err("invalid number", start)),
            }
        } else {
            match parse_integer(s) {
                Some(i) => Ok((start, Value::Int(i))),
                None => {
                    let first = s.chars().next().unwrap_or(' ');
                    if first.is_ascii_digit() || first == '-' {
                        Err(err("invalid number", start))
                    } else {
                        Err(err("invalid TOML value, did you mean to use a quoted string?", start))
                    }
                }
            }
        }
    }

    fn inline_table(&mut self) -> Res<()> {
        self.eat_whitespace()?;
        if self.eat(Token::RightBrace)? {
            return Ok(());
        }
        loop {
            let _key = self.dotted_key()?;
            self.eat_whitespace()?;
            self.expect(Token::Equals)?;
            self.eat_whitespace()?;
            self.value()?;
            self.eat_whitespace()?;
            if self.eat(Token::RightBrace)? {
                return Ok(());
            }
            self.expect(Token::Comma)?;
            self.eat_whitespace()?;
        }
    }

    fn array(&mut self) -> Res<(Vec<(usize, Value)>, usize)> {
        let mut ret = Vec::new();
        loop {
            self.intermediate()?;
            if self.eat(Token::RightBracket)? {
                return Ok((ret, 0));
            }
            let v = self.value()?;
            ret.push(v);
            self.intermediate()?;
            if !self.eat(Token::Comma)? {
                break;
            }
        }
        self.intermediate()?;
        self.expect(Token::RightBracket)?;
        Ok((ret, 0))
    }

    fn intermediate(&mut self) -> Res<()> {
        loop {
            self.eat_whitespace()?;
            if !self.eat(Token::Newline)? && !self.eat_comment()? {
                break;
            }
        }
        Ok(())
    }

    fn parse(&mut self) -> Res<Document> {
        let mut doc = Document { root: Vec::new() };
        let mut in_root = true;
        let mut tables: Vec<Vec<String>> = Vec::new();
        loop {
            loop {
                self.eat_whitespace()?;
                if self.eat_comment()? {
                    continue;
                }
                if self.eat(Token::Newline)? {
                    continue;
                }
                break;
            }
            match self.peek()? {
                None => break,
                Some((hstart, Token::LeftBracket)) => {
                    self.next()?;
                    let array = self.eat(Token::LeftBracket)?;
                    self.eat_whitespace()?;
                    let key = self.dotted_key()?;
                    self.expect(Token::RightBracket)?;
                    if array {
                        self.expect(Token::RightBracket)?;
                    }
                    self.eat_whitespace()?;
                    if !self.eat_comment()? {
                        self.eat_newline_or_eof()?;
                    }
                    if !array {
                        if tables.contains(&key) {
                            let mut e = err(
                                format!("redefinition of table `{}`", key.join(".")),
                                hstart,
                            );
                            e.key = key.clone();
                            return Err(e);
                        }
                        tables.push(key);
                    }
                    in_root = false;
                }
                Some(_) => {
                    let key = self.dotted_key()?;
                    self.eat_whitespace()?;
                    self.expect(Token::Equals)?;
                    self.eat_whitespace()?;
                    let (start, value) = self.value()?;
                    self.eat_whitespace()?;
                    if !self.eat_comment()? {
                        self.eat_newline_or_eof()?;
                    }
                    if in_root && key.len() == 1 {
                        doc.root.push((key[0].clone(), start, value));
                    }
                }
            }
        }
        Ok(doc)
    }
}

fn parse_integer(s: &str) -> Option<i64> {
    let (neg, digits) = if let Some(r) = s.strip_prefix('-') { (true, r) } else { (false, s) };
    let (radix, digits) = if let Some(r) = digits.strip_prefix("0x") {
        (16, r)
    } else if let Some(r) = digits.strip_prefix("0o") {
        (8, r)
    } else if let Some(r) = digits.strip_prefix("0b") {
        (2, r)
    } else {
        (10, digits)
    };
    if digits.is_empty() {
        return None;
    }
    if radix == 10 && digits.len() > 1 && digits.starts_with('0') {
        return None;
    }
    if digits.starts_with('_') || digits.ends_with('_') || digits.contains("__") {
        return None;
    }
    let clean: String = digits.chars().filter(|&c| c != '_').collect();
    let v = i64::from_str_radix(&clean, radix).ok()?;
    Some(if neg { -v } else { v })
}

fn parse_float(s: &str) -> Option<f64> {
    if s.contains("__") || s.ends_with('_') || s.starts_with('_') || s.contains("_.") || s.contains("._") {
        return None;
    }
    let clean: String = s.chars().filter(|&c| c != '_').collect();
    // reject leading zeros like 01.5
    let body = clean.trim_start_matches('-');
    if body.len() > 1 && body.starts_with('0') && body.as_bytes()[1].is_ascii_digit() {
        return None;
    }
    if body.ends_with('.') || body.starts_with('.') {
        return None;
    }
    clean.parse::<f64>().ok()
}

pub fn parse(input: &str) -> Result<Document, Error> {
    let mut p = Parser { tokens: Tokenizer { input, pos: 0 }, input };
    p.parse()
}

pub fn to_linecol(input: &str, offset: usize) -> (usize, usize) {
    let mut cur = 0;
    for (i, line) in input.split_terminator('\n').enumerate() {
        if cur + line.len() + 1 > offset {
            return (i, offset - cur);
        }
        cur += line.len() + 1;
    }
    (input.lines().count(), 0)
}

impl Error {
    pub fn display(&self, input: &str) -> String {
        let mut s = self.msg.clone();
        if !self.key.is_empty() {
            s.push_str(&format!(" for key `{}`", self.key.join(".")));
        }
        if let Some(at) = self.at {
            let (line, col) = to_linecol(input, at);
            s.push_str(&format!(" at line {} column {}", line + 1, col + 1));
        }
        s
    }
}

fn describe_value(v: &Value) -> String {
    match v {
        Value::Str(s) => format!("invalid type: string {:?}", s),
        Value::Int(i) => format!("invalid type: integer `{}`", i),
        Value::Float(f, text) => {
            let _ = text;
            format!("invalid type: floating point `{}`", fmt_float(*f))
        }
        Value::Bool(b) => format!("invalid type: boolean `{}`", b),
        Value::Datetime | Value::Table => "invalid type: map".to_string(),
        Value::Array(..) => "invalid type: sequence".to_string(),
    }
}

fn fmt_float(f: f64) -> String {
    if f.is_finite() && f.fract() == 0.0 && f.abs() < 1e16 {
        format!("{:.1}", f)
    } else {
        format!("{}", f)
    }
}

/// Deserialize a `Vec<String>` field from a value.
pub fn expect_string_list(key: &str, start: usize, v: &Value) -> Result<Vec<String>, Error> {
    match v {
        Value::Array(items, _) => {
            let mut out = Vec::new();
            for (istart, item) in items {
                match item {
                    Value::Str(s) => out.push(s.clone()),
                    Value::Array(..) => {
                        return Err(Error {
                            msg: format!("{}, expected a string", describe_value(item)),
                            at: Some(0),
                            key: vec![key.to_string()],
                        })
                    }
                    other => {
                        return Err(Error {
                            msg: format!("{}, expected a string", describe_value(other)),
                            at: Some(*istart),
                            key: vec![key.to_string()],
                        })
                    }
                }
            }
            Ok(out)
        }
        other => Err(Error {
            msg: format!("{}, expected a sequence", describe_value(other)),
            at: Some(start),
            key: vec![key.to_string()],
        }),
    }
}
