// Gitignore-style glob matching.

#[derive(Debug, Clone)]
enum Tok {
    Literal(char),
    Any,
    ZeroOrMore,
    RecursivePrefix,
    RecursiveSuffix,
    RecursiveZeroOrMore,
    Class { negated: bool, ranges: Vec<(char, char)> },
    Alternates(Vec<Vec<Tok>>),
}

#[derive(Debug, Clone)]
pub struct Glob {
    toks: Vec<Tok>,
    pub is_whitelist: bool,
    pub is_only_dir: bool,
}

fn parse_glob(pat: &str) -> Result<Vec<Tok>, String> {
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0;
    let (toks, _) = parse_seq(&chars, &mut i, false)?;
    Ok(toks)
}

fn parse_seq(chars: &[char], i: &mut usize, in_alt: bool) -> Result<(Vec<Tok>, bool), String> {
    let mut toks: Vec<Tok> = Vec::new();
    while *i < chars.len() {
        let c = chars[*i];
        match c {
            '\\' => {
                *i += 1;
                if *i < chars.len() {
                    toks.push(Tok::Literal(chars[*i]));
                    *i += 1;
                } else {
                    return Err("dangling '\\'".to_string());
                }
            }
            '?' => {
                toks.push(Tok::Any);
                *i += 1;
            }
            '*' => {
                let prev_is_sep_or_start = *i == 0 || chars[*i - 1] == '/';
                if *i + 1 < chars.len() && chars[*i + 1] == '*' {
                    // `**`
                    *i += 2;
                    let next = chars.get(*i).copied();
                    let at_start = toks.is_empty();
                    if prev_is_sep_or_start && (next.is_none() || next == Some('/')) {
                        if at_start && next.is_none() {
                            // `**` alone
                            toks.push(Tok::RecursivePrefix);
                            toks.push(Tok::ZeroOrMore);
                            // represents match everything
                            toks.clear();
                            toks.push(Tok::RecursiveSuffix);
                            // special-case: match anything
                            return Ok((vec![Tok::Alternates(vec![vec![Tok::RecursiveSuffix]])], false))
                                .map(|_| (vec![Tok::RecursiveSuffix], false))
                                .and_then(|_| Ok((match_all(), false)));
                        } else if at_start {
                            // `**/`
                            *i += 1;
                            toks.push(Tok::RecursivePrefix);
                        } else if next.is_none() {
                            // `/**`
                            if let Some(Tok::Literal('/')) = toks.last() {
                                toks.pop();
                            }
                            toks.push(Tok::RecursiveSuffix);
                        } else {
                            // `/**/`
                            if let Some(Tok::Literal('/')) = toks.last() {
                                toks.pop();
                            }
                            *i += 1;
                            toks.push(Tok::RecursiveZeroOrMore);
                        }
                    } else {
                        toks.push(Tok::ZeroOrMore);
                    }
                } else {
                    toks.push(Tok::ZeroOrMore);
                    *i += 1;
                }
            }
            '[' => {
                *i += 1;
                let mut negated = false;
                if *i < chars.len() && (chars[*i] == '!' || chars[*i] == '^') {
                    negated = true;
                    *i += 1;
                }
                let mut ranges = Vec::new();
                let mut first = true;
                loop {
                    if *i >= chars.len() {
                        return Err("unclosed character class; missing ']'".to_string());
                    }
                    let c = chars[*i];
                    if c == ']' && !first {
                        *i += 1;
                        break;
                    }
                    first = false;
                    *i += 1;
                    if *i + 1 < chars.len() && chars[*i] == '-' && chars[*i + 1] != ']' {
                        let hi = chars[*i + 1];
                        if hi < c {
                            return Err(format!("invalid range; '{}' > '{}'", c, hi));
                        }
                        ranges.push((c, hi));
                        *i += 2;
                    } else {
                        ranges.push((c, c));
                    }
                }
                toks.push(Tok::Class { negated, ranges });
            }
            '{' => {
                *i += 1;
                let mut alts = Vec::new();
                loop {
                    let (seq, closed) = parse_seq(chars, i, true)?;
                    alts.push(seq);
                    if closed {
                        break;
                    }
                    if *i >= chars.len() {
                        return Err("unclosed alternate group; missing '}'".to_string());
                    }
                }
                toks.push(Tok::Alternates(alts));
            }
            ',' if in_alt => {
                *i += 1;
                return Ok((toks, false));
            }
            '}' if in_alt => {
                *i += 1;
                return Ok((toks, true));
            }
            c => {
                toks.push(Tok::Literal(c));
                *i += 1;
            }
        }
    }
    if in_alt {
        return Err("unclosed alternate group; missing '}'".to_string());
    }
    Ok((toks, false))
}

fn match_all() -> Vec<Tok> {
    vec![Tok::RecursiveSuffix]
}

fn match_toks(toks: &[Tok], s: &[char]) -> bool {
    match toks.first() {
        None => s.is_empty(),
        Some(t) => {
            let rest = &toks[1..];
            match t {
                Tok::Literal(c) => !s.is_empty() && s[0] == *c && match_toks(rest, &s[1..]),
                Tok::Any => !s.is_empty() && s[0] != '/' && match_toks(rest, &s[1..]),
                Tok::ZeroOrMore => {
                    let mut k = 0;
                    loop {
                        if match_toks(rest, &s[k..]) {
                            return true;
                        }
                        if k >= s.len() || s[k] == '/' {
                            return false;
                        }
                        k += 1;
                    }
                }
                Tok::RecursivePrefix => {
                    // (?:/?|.*/)
                    if match_toks(rest, s) {
                        return true;
                    }
                    if !s.is_empty() && s[0] == '/' && match_toks(rest, &s[1..]) {
                        return true;
                    }
                    for k in 0..s.len() {
                        if s[k] == '/' && match_toks(rest, &s[k + 1..]) {
                            return true;
                        }
                    }
                    false
                }
                Tok::RecursiveSuffix => {
                    // as the whole pattern: match everything; otherwise `/.*`
                    if toks.len() == 1 && rest.is_empty() && false {
                        return true;
                    }
                    if !s.is_empty() && s[0] == '/' {
                        return match_toks_rest_any(rest, &s[1..]);
                    }
                    // pattern consisting only of `**`
                    false
                }
                Tok::RecursiveZeroOrMore => {
                    // (?:/|/.*/)
                    if s.is_empty() || s[0] != '/' {
                        return false;
                    }
                    if match_toks(rest, &s[1..]) {
                        return true;
                    }
                    for k in 1..s.len() {
                        if s[k] == '/' && match_toks(rest, &s[k + 1..]) {
                            return true;
                        }
                    }
                    false
                }
                Tok::Class { negated, ranges } => {
                    if s.is_empty() {
                        return false;
                    }
                    let c = s[0];
                    let inside = ranges.iter().any(|&(lo, hi)| lo <= c && c <= hi);
                    let ok = if *negated { !inside && c != '/' } else { inside };
                    ok && match_toks(rest, &s[1..])
                }
                Tok::Alternates(alts) => {
                    for alt in alts {
                        let mut combined: Vec<Tok> = alt.clone();
                        combined.extend_from_slice(rest);
                        if match_toks(&combined, s) {
                            return true;
                        }
                    }
                    false
                }
            }
        }
    }
}

fn match_toks_rest_any(rest: &[Tok], s: &[char]) -> bool {
    // `.*` followed by rest
    for k in 0..=s.len() {
        if match_toks(rest, &s[k..]) {
            return true;
        }
    }
    false
}

impl Glob {
    pub fn is_match(&self, path: &str) -> bool {
        let s: Vec<char> = path.chars().collect();
        if self.toks.len() == 1 {
            if let Tok::RecursiveSuffix = self.toks[0] {
                // `**` matches everything
                return true;
            }
        }
        match_toks(&self.toks, &s)
    }
}

pub struct Gitignore {
    root: String,
    globs: Vec<Glob>,
}

fn strip_prefix<'a>(prefix: &str, path: &'a str) -> Option<&'a str> {
    path.strip_prefix(prefix)
}

fn is_file_name(path: &str) -> bool {
    !path.contains('/')
}

pub enum Match {
    None,
    Ignore,
    Whitelist,
}

impl Gitignore {
    pub fn new(root: &str) -> Gitignore {
        let root = root.strip_prefix("./").unwrap_or(root).to_string();
        Gitignore { root, globs: Vec::new() }
    }

    pub fn add_line(&mut self, line: &str) -> Result<(), String> {
        if line.starts_with('#') {
            return Ok(());
        }
        let mut line = line;
        let trimmed;
        if !line.ends_with("\\ ") {
            trimmed = line.trim_end();
            line = trimmed;
        }
        if line.is_empty() {
            return Ok(());
        }
        let mut is_whitelist = false;
        let mut is_only_dir = false;
        let mut is_absolute = false;
        let mut line = line.to_string();
        if line.starts_with("\\!") || line.starts_with("\\#") {
            line = line[1..].to_string();
            is_absolute = line.starts_with('/');
        } else {
            if line.starts_with('!') {
                is_whitelist = true;
                line = line[1..].to_string();
            }
            if line.starts_with('/') {
                line = line[1..].to_string();
                is_absolute = true;
            }
        }
        if line.ends_with('/') {
            is_only_dir = true;
            line.pop();
            if line.ends_with('\\') {
                line.pop();
            }
        }
        let mut actual = line.clone();
        if !is_absolute && !line.contains('/') {
            if !actual.starts_with("**/") && actual != "**" {
                actual = format!("**/{}", actual);
            }
        }
        if actual.ends_with("/**") {
            actual = format!("{}/*", actual);
        }
        let toks = parse_glob(&actual)?;
        self.globs.push(Glob { toks, is_whitelist, is_only_dir });
        Ok(())
    }

    pub fn add_file(&mut self, path: &std::path::Path) {
        if let Ok(contents) = std::fs::read_to_string(path) {
            for line in contents.lines() {
                let _ = self.add_line(line);
            }
        }
    }

    pub fn matched(&self, path: &str, is_dir: bool) -> Match {
        if self.globs.is_empty() {
            return Match::None;
        }
        let mut p = path;
        if let Some(s) = strip_prefix("./", p) {
            p = s;
        }
        if self.root != "." && !is_file_name(p) {
            if let Some(s) = strip_prefix(&self.root, p) {
                p = s;
                if let Some(s) = strip_prefix("/", p) {
                    p = s;
                }
            }
        }
        for g in self.globs.iter().rev() {
            if g.is_match(p) && (!g.is_only_dir || is_dir) {
                return if g.is_whitelist { Match::Whitelist } else { Match::Ignore };
            }
        }
        Match::None
    }
}
EOF"}

