// --- strsim jaro-winkler ---
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a == b { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        for (j, b_elem) in b.iter().enumerate().take(max_bound + 1) {
            if min_bound <= j && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jd = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let jw = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean(v: &str, candidates: &[&str]) -> Vec<String> {
    let mut c: Vec<(f64, String)> = candidates
        .iter()
        .map(|pv| (jaro_winkler(v, pv), pv.to_string()))
        .filter(|(conf, _)| *conf > 0.8)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.into_iter().map(|(_, s)| s).collect()
}

const SUBCOMMANDS: &[&str] = &["check", "fix", "single", "explain", "dump", "list", "help"];

fn unknown_argument(arg: &str, suggestion: Option<&str>, usage: &str) -> String {
    let mut s = format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", arg);
    if let Some(sugg) = suggestion {
        s.push_str(&format!("\n\tDid you mean '{}'?\n", sugg));
    }
    if arg.starts_with('-') {
        s.push_str(&format!(
            "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
            arg, arg
        ));
    }
    s.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage));
    s
}

pub fn parse_warning_code(src: &str) -> Result<u32, String> {
    let mut chars = src.chars();
    let severity = match chars.next() {
        Some(c) => c.to_ascii_lowercase(),
        None => return Err(format!("unable to parse `{}` as warning code", src)),
    };
    match severity {
        'w' => chars
            .collect::<String>()
            .parse::<u32>()
            .map_err(|_| format!("unable to parse `{}` as warning code", src)),
        _ => Ok(0),
    }
}

fn parse_line_col(src: &str) -> Result<(usize, usize), String> {
    let parts: Vec<&str> = src.split(',').collect();
    let err = || format!("unable to parse `{}` as line and column", src);
    match parts.as_slice() {
        [line, col] => {
            let l = line.parse::<usize>().map_err(|_| err())?;
            let c = col.parse::<usize>().map_err(|_| err())?;
            Ok((l, c))
        }
        _ => Err(err()),
    }
}

fn parse_format(src: &str) -> Result<OutFormat, String> {
    match src.to_ascii_lowercase().as_str() {
        "json" => Err("statix was not compiled with the `json` feature flag".to_string()),
        "errfmt" => Ok(OutFormat::Errfmt),
        "stderr" => Ok(OutFormat::Stderr),
        _ => Err("unknown output format, try: json, errfmt".to_string()),
    }
}

struct Matched {
    order: Vec<&'static str>,
    values: Vec<(&'static str, Vec<String>)>,
}

impl Matched {
    fn contains(&self, id: &str) -> bool {
        self.order.iter().any(|&o| o == id)
    }
    fn add(&mut self, id: &'static str) {
        if !self.contains(id) {
            self.order.push(id);
            self.values.push((id, Vec::new()));
        }
    }
    fn push_value(&mut self, id: &'static str, v: String) {
        self.add(id);
        for (i, vals) in self.values.iter_mut() {
            if *i == id {
                vals.push(v);
                return;
            }
        }
    }
    fn get(&self, id: &str) -> Option<&Vec<String>> {
        self.values.iter().find(|(i, _)| *i == id).map(|(_, v)| v)
    }
}

fn smart_usage(bin: &str, cmd: Cmd, specs: &[ArgSpec], used: &[&'static str]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut seen: Vec<&str> = Vec::new();
    // required non-positionals, then used non-positionals
    for s in specs.iter().filter(|s| s.required && !s.positional) {
        parts.push(s.display());
        seen.push(s.id);
    }
    for u in used {
        if let Some(s) = specs.iter().find(|s| s.id == *u) {
            if !s.positional && !seen.contains(&s.id) {
                parts.push(s.display());
                seen.push(s.id);
            }
        }
    }
    for s in specs.iter().filter(|s| s.positional) {
        if s.required || used.contains(&s.id) {
            parts.push(s.display());
        }
    }
    let mut out = format!("{} {}", bin, cmd_name(cmd));
    for p in parts {
        out.push(' ');
        out.push_str(&p);
    }
    out
}

fn usage_for(bin: &str, cmd: Cmd, specs: &[ArgSpec], used: &[&'static str]) -> String {
    if used.is_empty() {
        full_usage(bin, cmd)
    } else {
        smart_usage(bin, cmd, specs, used)
    }
}

fn used_non_required(specs: &[ArgSpec], m: &Matched) -> Vec<&'static str> {
    m.order
        .iter()
        .copied()
        .filter(|id| specs.iter().find(|s| s.id == *id).map_or(true, |s| !s.required))
        .collect()
}

pub fn parse_args(args: Vec<String>) -> Opts {
    let argv0 = args.first().cloned().unwrap_or_else(|| "statix".to_string());
    let bin = std::path::Path::new(&argv0)
        .file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| argv0.clone());
    let rest = &args[1.min(args.len())..];

    if rest.is_empty() {
        let text = help_text("main").replace("{bin}", &bin);
        let _ = std::io::stdout().flush();
        let mut e = std::io::stderr();
        let _ = e.write_all(text.as_bytes());
        let _ = e.flush();
        std::process::exit(2);
    }

    let top_usage = format!("{} <SUBCOMMAND>", bin);
    let mut i = 0;
    while i < rest.len() {
        let a = &rest[i];
        if a == "--" {
            i += 1;
            continue;
        }
        if let Some(long) = a.strip_prefix("--") {
            let (name, value) = match long.find('=') {
                Some(p) => (&long[..p], Some(&long[p..])),
                None => (long, None),
            };
            match name {
                "help" | "version" => {
                    if let Some(v) = value {
                        let usage = if name == "help" {
                            format!("{} --help", bin)
                        } else {
                            format!("{} --version", bin)
                        };
                        let _ = usage;
                        exit_error(&format!(
                            "error: The value '{}' was provided to '--{}' but it wasn't expecting any more values\n\n{}\n\nFor more information try --help\n",
                            v, name, top_usage
                        ));
                    }
                    if name == "help" {
                        print_help_and_exit(&bin, "main");
                    } else {
                        println!("statix 0.5.8");
                        std::process::exit(0);
                    }
                }
                _ => {
                    let sugg = did_you_mean(name, &["help", "version"]).pop();
                    let usage = match &sugg {
                        Some(s) => format!("{} --{}", bin, s),
                        None => top_usage.clone(),
                    };
                    let sugg_flag = sugg.map(|s| format!("--{}", s));
                    exit_error(&unknown_argument(a, sugg_flag.as_deref(), &usage));
                }
            }
        } else if a.starts_with('-') && a.len() > 1 {
            for c in a[1..].chars() {
                match c {
                    'h' => print_help_and_exit(&bin, "main"),
                    'V' => {
                        println!("statix 0.5.8");
                        std::process::exit(0);
                    }
                    c => {
                        exit_error(&unknown_argument(&format!("-{}", c), None, &top_usage));
                    }
                }
            }
            i += 1;
            continue;
        } else {
            let cmd = match a.as_str() {
                "check" => Cmd::Check,
                "fix" => Cmd::Fix,
                "single" => Cmd::Single,
                "explain" => Cmd::Explain,
                "list" => Cmd::List,
                "dump" => Cmd::Dump,
                "help" => {
                    handle_help(&bin, &rest[i + 1..]);
                }
                other => {
                    let cands = did_you_mean(other, SUBCOMMANDS);
                    if !cands.is_empty() {
                        let dym = cands.iter().map(|c| format!("'{}'", c)).collect::<Vec<_>>().join(" or ");
                        exit_error(&format!(
                            "error: The subcommand '{}' wasn't recognized\n\n\tDid you mean {}?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                            other, dym, bin, other, top_usage
                        ));
                    }
                    exit_error(&unknown_argument(other, None, &top_usage));
                }
            };
            return parse_subcommand(&bin, cmd, &rest[i + 1..]);
        }
    }
    // only "--" given
    let text = help_text("main").replace("{bin}", &bin);
    let _ = std::io::stderr().write_all(text.as_bytes());
    std::process::exit(2);
}

fn handle_help(bin: &str, rest: &[String]) -> ! {
    if rest.is_empty() {
        print_help_and_exit(bin, "main");
    }
    let first = &rest[0];
    let known = ["check", "fix", "single", "explain", "list", "dump", "help"];
    let unrec = |name: &str| -> ! {
        exit_error(&format!(
            "error:  The subcommand '{}' wasn't recognized\n\nUSAGE:\n    {} <subcommands>\n\nFor more information try --help\n",
            name, bin
        ));
    };
    if !known.contains(&first.as_str()) {
        unrec(first);
    }
    if rest.len() > 1 {
        unrec(&rest[1]);
    }
    print_help_and_exit(bin, first);
}

fn parse_subcommand(bin: &str, cmd: Cmd, args: &[String]) -> Opts {
    let specs = cmd_args(cmd);
    let mut m = Matched { order: Vec::new(), values: Vec::new() };
    let mut trailing = false;
    let mut i = 0;
    // option awaiting a value: (spec, got_any_value)
    let mut pending: Option<(ArgSpec, bool)> = None;
    let name = cmd_name(cmd);

    let longs: Vec<&str> = specs.iter().filter_map(|s| s.long).collect();

    while i < args.len() {
        let a = &args[i];
        i += 1;

        if !trailing {
            if let Some((spec, got)) = pending {
                let is_flag_like = a.starts_with('-') && a.len() > 1;
                if !is_flag_like {
                    m.push_value(spec.id, a.clone());
                    if spec.multiple {
                        pending = Some((spec, true));
                    } else {
                        pending = None;
                    }
                    continue;
                } else if !got {
                    // option followed by a flag: missing value
                    exit_error(&format!(
                        "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                        spec.display(),
                        full_usage(bin, cmd)
                    ));
                } else {
                    pending = None;
                }
            }
        }

        if !trailing && a == "--" {
            trailing = true;
            pending = None;
            continue;
        }

        if !trailing && a.starts_with("--") {
            let long = &a[2..];
            let (lname, value) = match long.find('=') {
                Some(p) => (&long[..p], Some(long[p + 1..].to_string())),
                None => (long, None),
            };
            if lname == "help" {
                if value.is_some() {
                    let used = used_non_required(&specs, &m);
                    let usage = usage_for(bin, cmd, &specs, &used);
                    exit_error(&format!(
                        "error: The value '={}' was provided to '--help' but it wasn't expecting any more values\n\n{}\n\nFor more information try --help\n",
                        value.unwrap(),
                        usage
                    ));
                }
                print_help_and_exit(bin, name);
            }
            let spec = match specs.iter().find(|s| s.long == Some(lname)) {
                Some(s) => *s,
                None => {
                    let sugg = did_you_mean(lname, &longs).pop();
                    if let Some(sg) = &sugg {
                        if let Some(s) = specs.iter().find(|s| s.long == Some(sg.as_str())) {
                            m.add(s.id);
                        }
                    }
                    let used = used_non_required(&specs, &m);
                    let usage = usage_for(bin, cmd, &specs, &used);
                    let sugg_flag = sugg.map(|s| format!("--{}", s));
                    exit_error(&unknown_argument(a, sugg_flag.as_deref(), &usage));
                }
            };
            if m.contains(spec.id) {
                exit_error(&format!(
                    "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                    spec.display(),
                    full_usage(bin, cmd)
                ));
            }
            if !spec.takes_value() {
                if let Some(v) = value {
                    let used = used_non_required(&specs, &m);
                    let usage = usage_for(bin, cmd, &specs, &used);
                    exit_error(&format!(
                        "error: The value '={}' was provided to '{}' but it wasn't expecting any more values\n\n{}\n\nFor more information try --help\n",
                        v,
                        spec.display(),
                        usage
                    ));
                }
                m.add(spec.id);
            } else if let Some(v) = value {
                m.push_value(spec.id, v);
                if spec.multiple {
                    pending = Some((spec, true));
                }
            } else {
                m.add(spec.id);
                pending = Some((spec, false));
            }
            continue;
        }

        if !trailing && a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                j += 1;
                if c == 'h' {
                    print_help_and_exit(bin, name);
                }
                let spec = match specs.iter().find(|s| s.short == Some(c)) {
                    Some(s) => *s,
                    None => {
                        exit_error(&unknown_argument(&format!("-{}", c), None, &full_usage(bin, cmd)));
                    }
                };
                if m.contains(spec.id) {
                    exit_error(&format!(
                        "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                        spec.display(),
                        full_usage(bin, cmd)
                    ));
                }
                if !spec.takes_value() {
                    m.add(spec.id);
                    continue;
                }
                let rest: String = chars[j..].iter().collect();
                let rest = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                if !rest.is_empty() || (j < chars.len()) {
                    m.push_value(spec.id, rest);
                    if spec.multiple {
                        pending = Some((spec, true));
                    }
                } else {
                    m.add(spec.id);
                    pending = Some((spec, false));
                }
                break;
            }
            continue;
        }

        // positional
        let target_spec = specs.iter().find(|s| s.positional).copied();
        match target_spec {
            Some(s) if !m.contains(s.id) => {
                m.push_value(s.id, a.clone());
            }
            _ => {
                exit_error(&unknown_argument(a, None, &full_usage(bin, cmd)));
            }
        }
    }

    if let Some((spec, got)) = pending {
        if !got {
            exit_error(&format!(
                "error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
                spec.display(),
                full_usage(bin, cmd)
            ));
        }
    }

    // required
    let missing: Vec<&ArgSpec> = specs.iter().filter(|s| s.required && !m.contains(s.id)).collect();
    if !missing.is_empty() {
        let used = used_non_required(&specs, &m);
        let usage = usage_for(bin, cmd, &specs, &used);
        let mut msg = String::from("error: The following required arguments were not provided:\n");
        for s in &missing {
            msg.push_str(&format!("    {}\n", s.display()));
        }
        msg.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n", usage));
        exit_error(&msg);
    }

    let invalid = |spec_disp: &str, e: &str| -> ! {
        exit_error(&format!(
            "error: Invalid value for '{}': {}\n\nFor more information try --help\n",
            spec_disp, e
        ));
    };

    let mut opts = Opts {
        cmd,
        target: None,
        ignore: Vec::new(),
        unrestricted: m.contains("unrestricted"),
        format: OutFormat::Stderr,
        conf_path: ".".to_string(),
        streaming: m.contains("streaming"),
        diff_only: m.contains("diff_only"),
        position: (0, 0),
        explain_code: 0,
    };

    for id in m.order.clone() {
        let vals = m.get(id).cloned().unwrap_or_default();
        let spec = specs.iter().find(|s| s.id == id).copied().unwrap();
        match id {
            "target" => {
                let v = vals.first().cloned().unwrap_or_default();
                if cmd == Cmd::Explain {
                    match parse_warning_code(&v) {
                        Ok(c) => opts.explain_code = c,
                        Err(e) => invalid(&spec.display(), &e),
                    }
                }
                opts.target = Some(v);
            }
            "ignore" => opts.ignore = vals,
            "format" => {
                let v = vals.first().cloned().unwrap_or_default();
                match parse_format(&v) {
                    Ok(f) => opts.format = f,
                    Err(e) => invalid(&spec.display(), &e),
                }
            }
            "conf_path" => opts.conf_path = vals.first().cloned().unwrap_or_default(),
            "position" => {
                let v = vals.first().cloned().unwrap_or_default();
                match parse_line_col(&v) {
                    Ok(p) => opts.position = p,
                    Err(e) => invalid(&spec.display(), &e),
                }
            }
            _ => {}
        }
    }
    if opts.target.is_none() && matches!(cmd, Cmd::Check | Cmd::Fix) {
        opts.target = Some(".".to_string());
    }
    opts
}
EOF"}

