#[derive(Default, Debug, Clone)]
pub struct ConfFile {
    pub disabled: Vec<String>,
    pub ignore: Vec<String>,
}

fn from_path(path: &Path) -> Result<ConfFile, String> {
    let contents = std::fs::read_to_string(path).map_err(|e| format!("path error: {}", e))?;
    let doc = toml::parse(&contents)
        .map_err(|e| format!("unable to parse config file: {}", e.display(&contents)))?;
