// Walking the file system for nix files, respecting ignore globs.
use crate::glob::{Gitignore, Match};
use std::path::{Path, PathBuf};

pub fn build_ignore_set(ignores: &[String], target: &Path, unrestricted: bool) -> Result<Gitignore, String> {
    let gitignore_path = target.join(".gitignore");
    let mut gi = Gitignore::new(&gitignore_path.to_string_lossy());
    if !unrestricted {
        gi.add_file(&gitignore_path);
    }
    for i in ignores {
        gi.add_line(i).map_err(|e| format!("error parsing glob '{}': {}", i, e))?;
    }
    Ok(gi)
}

fn not_ignored(m: Match) -> bool {
    matches!(m, Match::None | Match::Whitelist)
}

pub fn walk_nix_files(ignore: &Gitignore, target: &Path) -> Result<Vec<PathBuf>, String> {
    if !target.exists() {
        return Err(format!("file not found: {}", target.display()));
    }
    let mut files = Vec::new();
    if target.is_dir() {
        let mut dirs = vec![target.to_path_buf()];
        while let Some(dir) = dirs.pop() {
            if !dir.is_dir() {
                continue;
            }
            if !not_ignored(ignore.matched(&dir.to_string_lossy(), true)) {
                continue;
            }
            let rd = match std::fs::read_dir(&dir) {
                Ok(rd) => rd,
                Err(_) => continue,
            };
            let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok()).map(|e| e.path()).collect();
            entries.sort();
            for path in entries {
                if path.is_dir() {
                    dirs.push(path);
                } else if path.is_file() && not_ignored(ignore.matched(&path.to_string_lossy(), false)) {
                    files.push(path);
                }
            }
        }
    } else {
        files.push(target.to_path_buf());
    }
    let mut files: Vec<PathBuf> =
        files.into_iter().filter(|p| p.extension().map_or(false, |e| e == "nix")).collect();
    files.sort();
    Ok(files)
}
