mod diff;
mod glob;
mod kinds;
mod lexer;
mod lints;
mod make;
mod parser;
mod render;
mod report;
mod toml;
mod tree;
mod util;
mod walk;

use cli::{Cmd, OutFormat, Opts};
use report::{Report, Severity};
use std::io::{BufRead, Write};
use std::path::Path;
use tree::Tree;

struct VfsEntry {
    path: String,
    contents: String,
}

fn read_stdin(location: &str) -> String {
    let stdin = std::io::stdin();
    let mut lines = Vec::new();
    for line in stdin.lock().lines() {
        match line {
            Ok(l) => lines.push(l),
            Err(e) => util::panic_at(
                location,
                &format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
            ),
        }
    }
    lines.join("\n")
}

fn vfs_from_paths(paths: Vec<std::path::PathBuf>) -> Vec<VfsEntry> {
    let mut out = Vec::new();
    for p in paths {
        let display = p.to_string_lossy().into_owned();
        match std::fs::read(&p) {
            Ok(bytes) => match String::from_utf8(bytes) {
                Ok(s) => out.push(VfsEntry { path: display, contents: s }),
                Err(_) => {
                    println!("`{}` contains non-utf8 content", display);
                }
            },
            Err(_) => {}
        }
    }
    out
}

fn config_error(msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    eprintln!("config error: {}", msg);
    std::process::exit(0);
}

fn build_vfs(opts: &Opts, stdin_location: &str) -> Vec<VfsEntry> {
    if opts.streaming {
        let src = read_stdin(stdin_location);
        vec![VfsEntry { path: "<stdin>".to_string(), contents: src }]
    } else {
        let target = opts.target.clone().unwrap_or_else(|| ".".to_string());
        let target_path = Path::new(&target);
        let conf = match config::discover(&opts.conf_path) {
            Ok(c) => c,
            Err(e) => config_error(&e),
        };
        let mut ignores = opts.ignore.clone();
        ignores.extend(conf.ignore.iter().cloned());
        let ignore = match walk::build_ignore_set(&ignores, target_path, opts.unrestricted) {
            Ok(i) => i,
            Err(e) => config_error(&e),
        };
        let files = match walk::walk_nix_files(&ignore, target_path) {
            Ok(f) => f,
            Err(e) => config_error(&format!("path error: {}", e)),
        };
        vfs_from_paths(files)
    }
}

fn load_disabled(opts: &Opts) -> Vec<String> {
    match config::discover(&opts.conf_path) {
        Ok(c) => c.disabled,
        Err(e) => config_error(&e),
    }
}

fn lint_source(src: &str, disabled: &[String]) -> Vec<Report> {
    let parsed = parser::parse(src);
    let tree = Tree::from_green(&parsed.green);
    let mut reports = lints::lint_tree(&tree, disabled);
    for e in &parsed.errors {
        reports.push(report::from_parse_err(e));
    }
    reports
}

fn colorize(message: &str) -> String {
    message
        .split('`')
        .enumerate()
        .map(|(idx, part)| {
            if idx % 2 == 1 {
                format!("\x1b[36m{}\x1b[0m", part)
            } else {
                part.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("")
}

fn line_of(at: usize, src: &str) -> usize {
    src[..at].chars().filter(|&c| c == '\n').count() + 1
}

fn column_of(at: usize, src: &str) -> usize {
    src[..at].rfind('\n').map(|c| at - c).unwrap_or(at + 1)
}

fn write_report(out: &mut impl Write, entry: &VfsEntry, report: &Report, format: OutFormat) {
    match format {
        OutFormat::Errfmt => {
            for d in &report.diagnostics {
                let _ = writeln!(
                    out,
                    "{}>{}:{}:{}:{}:{}",
                    entry.path,
                    line_of(d.at.0, &entry.contents),
                    column_of(d.at.0, &entry.contents),
                    match report.severity {
                        Severity::Warn => "W",
                        Severity::Error => "E",
                    },
                    report.code,
                    d.message
                );
            }
        }
        OutFormat::Stderr => {
            let offset = report.diagnostics.iter().map(|d| d.at.0).min().unwrap_or(0);
            let kind = match report.severity {
                Severity::Warn => render::ReportKind::Warning,
                Severity::Error => render::ReportKind::Error,
            };
            let labels: Vec<render::Label> = report
                .diagnostics
                .iter()
                .map(|d| render::Label {
                    start: d.at.0,
                    end: d.at.1,
                    msg: colorize(&d.message),
                    color: Some(render::Color::Magenta),
                })
                .collect();
            let text = render::render(
                kind,
                &report.code_string(),
                &report.note,
                &entry.path,
                &entry.contents,
                offset,
                &labels,
            );
            let _ = out.write_all(text.as_bytes());
            let _ = out.flush();
        }
    }
}

fn run_check(opts: &Opts) {
    let vfs = build_vfs(opts, "bin/src/config.rs:74:28");
    let disabled = load_disabled(opts);
    let results: Vec<(usize, Vec<Report>)> =
        vfs.iter().enumerate().map(|(i, e)| (i, lint_source(&e.contents, &disabled))).collect();
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    if results.iter().any(|(_, r)| !r.is_empty()) {
        for (i, reports) in &results {
            for r in reports {
                write_report(&mut out, &vfs[*i], r, opts.format);
            }
        }
        let _ = out.flush();
        std::process::exit(1);
    }
}

// --- fixing ---

fn collect_fixes(src: &str, disabled: &[String]) -> Option<Vec<Report>> {
    let parsed = parser::parse(src);
    if !parsed.errors.is_empty() {
        return None;
    }
    let tree = Tree::from_green(&parsed.green);
    Some(
        lints::lint_tree(&tree, disabled)
            .into_iter()
            .filter(|r| r.total_suggestion_range().is_some())
            .collect(),
    )
}

fn reorder(mut reports: Vec<Report>) -> Vec<Report> {
    reports.sort_by_key(|r| r.total_suggestion_range().unwrap().1);
    let mut deque: std::collections::VecDeque<Report> = std::collections::VecDeque::new();
    for r in reports {
        let range = r.total_suggestion_range().unwrap();
        match deque.front().map(|f| f.total_suggestion_range().unwrap()) {
            Some(front) => {
                if range.0 > front.1 {
                    deque.push_front(r);
                }
            }
            None => deque.push_front(r),
        }
    }
    deque.into_iter().collect()
}

fn fix_all(src: &str, disabled: &[String]) -> Option<String> {
    if !parser::parse(src).errors.is_empty() {
        return None;
    }
    let mut cur = src.to_string();
    let mut changed = false;
    let mut iterations = 0;
    loop {
        let reports = match collect_fixes(&cur, disabled) {
            Some(r) => r,
            None => break,
        };
        if reports.is_empty() {
            break;
        }
        for r in reorder(reports) {
            r.apply(&mut cur);
        }
        changed = true;
        iterations += 1;
        if iterations > 100_000 {
            break;
        }
    }
    if changed {
        Some(cur)
    } else {
        None
    }
}

fn run_fix(opts: &Opts) {
    let vfs = build_vfs(opts, "bin/src/config.rs:127:28");
    let disabled = load_disabled(opts);
    for entry in &vfs {
        let fixed = fix_all(&entry.contents, &disabled);
        if opts.diff_only {
            let src = fixed.as_deref().unwrap_or(&entry.contents);
            let d = diff::unified_diff(
                &entry.contents,
                src,
                &entry.path,
                &format!("{} [fixed]", entry.path),
            );
            println!("{}", d);
        } else if opts.streaming {
            let src = fixed.as_deref().unwrap_or(&entry.contents);
            println!("{}", src);
        } else if let Some(f) = fixed {
            if let Err(e) = std::fs::write(&entry.path, f) {
                let _ = std::io::stdout().flush();
                eprintln!("fix error: {}", e);
                std::process::exit(0);
            }
        }
    }
}

// --- single ---

fn pos_to_byte(line: usize, col: usize, src: &str) -> Result<usize, String> {
    let mut byte = 0usize;
    for (l, i) in src.split_inclusive('\n').zip(1..) {
        if i >= line {
            break;
        }
        byte += l.len();
    }
    byte += col;
    if byte >= src.len() {
        Err(format!("position out of bounds: line {}, col {}", line, col))
    } else {
        Ok(byte)
    }
}

fn single_fix(line: usize, col: usize, src: &str) -> Result<String, String> {
    let offset = pos_to_byte(line, col, src)?;
    let parsed = parser::parse(src);
    let tree = Tree::from_green(&parsed.green);
    for id in tree.preorder_with_tokens(tree.root()) {
        let (s, e) = tree.range(id);
        if !(s <= offset && offset < e) {
            continue;
        }
        for &code in lints::lints_for_kind(tree.kind(id)) {
            if let Some(r) = lints::run_lint(code, &tree, id) {
                if r.total_suggestion_range().is_some() {
                    let mut out = src.to_string();
                    r.apply(&mut out);
                    return Ok(out);
                }
            }
        }
    }
    Err("nothing to fix".to_string())
}

fn run_single(opts: &Opts) {
    let entry = if opts.streaming {
        let src = read_stdin("bin/src/config.rs:183:28");
        VfsEntry { path: "<stdin>".to_string(), contents: src }
    } else {
        let target = match &opts.target {
            Some(t) => t.clone(),
            None => util::panic_at(
                "bin/src/config.rs:188:68",
                "called `Option::unwrap()` on a `None` value",
            ),
        };
        match std::fs::read_to_string(&target) {
            Ok(s) => VfsEntry { path: "<stdin>".to_string(), contents: s },
            Err(e) => config_error(&format!("path error: {}", e)),
        }
    };
    let (line, col) = opts.position;
    let result = single_fix(line, col, &entry.contents);
    if opts.diff_only {
        let src = result.as_deref().unwrap_or(&entry.contents);
        let d = diff::unified_diff(&entry.contents, src, &entry.path, &format!("{} [fixed]", entry.path));
        println!("{}", d);
    } else if opts.streaming {
        let src = result.as_deref().unwrap_or(&entry.contents);
        println!("{}", src);
    } else {
        match result {
            Ok(s) => {
                if let Err(e) = std::fs::write(&entry.path, s) {
                    let _ = std::io::stdout().flush();
                    eprintln!("fix error: {}", e);
                }
            }
            Err(e) => {
                let _ = std::io::stdout().flush();
                eprintln!("single fix error: {}", e);
            }
        }
    }
}

fn explanation(code: u32) -> Option<&'static str> {
    Some(match code {
        1 => include_str!("text/W01.md"),
        2 => include_str!("text/W02.md"),
        3 => include_str!("text/W03.md"),
        4 => include_str!("text/W04.md"),
        5 => include_str!("text/W05.md"),
        6 => include_str!("text/W06.md"),
        7 => include_str!("text/W07.md"),
        8 => include_str!("text/W08.md"),
        10 => include_str!("text/W10.md"),
        11 => include_str!("text/W11.md"),
        12 => include_str!("text/W12.md"),
        14 => include_str!("text/W14.md"),
        17 => include_str!("text/W17.md"),
        18 => include_str!("text/W18.md"),
        19 => include_str!("text/W19.md"),
        20 => include_str!("text/W20.md"),
        23 => include_str!("text/W23.md"),
        _ => return None,
    })
}

fn run_explain(opts: &Opts) {
    let code = opts.explain_code;
    if code == 0 {
        println!("syntax error");
        return;
    }
    match explanation(code) {
        Some(text) => {
            print!("{}", text);
        }
        None => {
            eprintln!("explain error: lint with code `{}` not found", code);
        }
    }
}

fn run_list() {
    for l in lints::LINTS {
        println!("W{:02} {}", l.code, l.name);
    }
}

fn run_dump() {
    println!("disabled = []\nignore = ['.direnv']\n");
}

fn main() {
    let args: Vec<String> = std::env::args_os().map(|a| a.to_string_lossy().into_owned()).collect();
    let opts = cli::parse_args(args);
    match opts.cmd {
        Cmd::Check => run_check(&opts),
        Cmd::Fix => run_fix(&opts),
        Cmd::Single => run_single(&opts),
        Cmd::Explain => run_explain(&opts),
        Cmd::List => run_list(),
        Cmd::Dump => run_dump(),
    }
    let _ = std::io::stdout().flush();
}
