            Err(e) => config_error(&format!("path error: {}", e)),
        }
    };
    let (line, col) = opts.position;
    let result = single_fix(line, col, &entry.contents);
    if opts.diff_only {
        let src = result.as_deref().unwrap_or(&entry.contents);
        let d = diff::unified_diff(&entry.contents, src, &entry.path, &format!("{} [fixed]", entry.path));
        println!("{}", d);
    } else if opts.streaming {
        let src = result.as_deref().unwrap_or(&entry.contents);
        println!("{}", src);
    } else {
        match result {
            Ok(s) => {
                if let Err(e) = std::fs::write(&entry.path, s) {
                    let _ = std::io::stdout().flush();
                    eprintln!("fix error: {}", e);
                }
            }
            Err(e) => {
                let _ = std::io::stdout().flush();
                eprintln!("single fix error: {}", e);
            }
        }
    }
}

fn explanation(code: u32) -> Option<&'static str> {
    Some(match code {
        1 => include_str!("text/W01.md"),
        2 => include_str!("text/W02.md"),
        3 => include_str!("text/W03.md"),
        4 => include_str!("text/W04.md"),
        5 => include_str!("text/W05.md"),
        6 => include_str!("text/W06.md"),
        7 => include_str!("text/W07.md"),
        8 => include_str!("text/W08.md"),
        10 => include_str!("text/W10.md"),
        11 => include_str!("text/W11.md"),
        12 => include_str!("text/W12.md"),
        14 => include_str!("text/W14.md"),
        17 => include_str!("text/W17.md"),
        18 => include_str!("text/W18.md"),
        19 => include_str!("text/W19.md"),
        20 => include_str!("text/W20.md"),
        23 => include_str!("text/W23.md"),
        _ => return None,
    })
}

fn run_explain(opts: &Opts) {
    let code = opts.explain_code;
    if code == 0 {
        println!("syntax error");
        return;
    }
    match explanation(code) {
        Some(text) => {
            print!("{}", text);
        }
        None => {
            eprintln!("explain error: lint with code `{}` not found", code);
        }
    }
}

fn run_list() {
    for l in lints::LINTS {
        println!("W{:02} {}", l.code, l.name);
    }
}

fn run_dump() {
    println!("disabled = []\nignore = ['.direnv']\n");
}

fn main() {
    let args: Vec<String> = std::env::args_os().map(|a| a.to_string_lossy().into_owned()).collect();
    let opts = cli::parse_args(args);
    match opts.cmd {
        Cmd::Check => run_check(&opts),
        Cmd::Fix => run_fix(&opts),
        Cmd::Single => run_single(&opts),
        Cmd::Explain => run_explain(&opts),
        Cmd::List => run_list(),
        Cmd::Dump => run_dump(),
    }
    let _ = std::io::stdout().flush();
}
